/* =========================================================
   PartyRent — Supplier Mode pages
   A supplier only ever sees records for its own shop
   (filtered by session.user.supplierId).
   ========================================================= */
(function () {
  'use strict';
  const { esc, url, $, $$ } = U;
  const I = Icons.icon;
  const SP = Pages.supplier = {};
  const Sh = () => Pages.shared;

  const sid = ctx => ctx.session.user.supplierId;
  const myReqs = ctx => Store.where('requests', r => r.supplierId === sid(ctx));
  const myProds = ctx => Store.where('products', p => p.supplierId === sid(ctx) && p.status !== 'archived' && p.status !== 'deleted');
  // one status badge for the three listing statuses (Active / Hidden by admin / Inactive)
  const lstBadge = (kind, x) => { const L = Services.LISTING[Services.listingStatus(kind, x)]; return '<span class="badge ' + L[1] + '">' + L[0] + '</span>'; };
  const reqItems = r => r.lines.map(l => (l.type === 'package' ? '📦 ' : '') + esc(Services.itemName(l))).join(', ');
  const reqQty = r => U.sum(r.lines, l => U.sum(Object.values(l.days), Number));
  const ownReq = (ctx, id) => { const r = Store.request(id); return r && r.supplierId === sid(ctx) ? r : null; };
  function conflictsFor(r) {
    if (r.status !== 'pending') return [];
    return Inventory.check(r.lines, { excludeRequestId: r.id }).bad;
  }

  /* ================= DASHBOARD ================= */
  SP.dashboard = function (ctx) {
    const sup = Store.supplier(sid(ctx)); const reqs = myReqs(ctx); const prods = myProds(ctx);
    const T = U.today();
    const snap = prods.map(p => Inventory.breakdown(p.id, T));
    const fins = reqs.filter(r => Finance.ACTIVE.includes(r.status) || r.status === 'completed').map(r => ({ r, f: Finance.summary(r) }));
    const pend = reqs.filter(r => r.status === 'pending');
    const upcoming = reqs.filter(r => ['accepted', 'in_progress', 'ready_pickup', 'out_delivery'].includes(r.status)).sort((a, b) => a.start.localeCompare(b.start));
    const months = Charts.months(6);
    const myIds = new Set(reqs.map(r => r.id));
    const ver = Store.where('payments', p => myIds.has(p.requestId) && p.status === 'verified' && Finance.RENTAL_TYPES.includes(p.type));
    const refunds = Store.where('payments', p => myIds.has(p.requestId) && p.status === 'verified' && p.type === 'refund');
    const revBy = m => U.sum(ver.filter(p => p.date.slice(0, 7) === m), p => p.amount) - U.sum(refunds.filter(p => p.date.slice(0, 7) === m), p => p.amount);
    const thisMonth = revBy(T.slice(0, 7));
    const pendingPay = Store.where('payments', p => myIds.has(p.requestId) && p.status === 'pending');
    const money = Auth.orgCan('payments.view', ctx.session.user), canProd = Auth.orgCan('products.manage', ctx.session.user);
    ctx.el.innerHTML = '<div class="page-head"><div><h1>Good day, ' + esc(ctx.session.user.name.split(' ')[0]) + '! ' + esc(sup.logo) + '</h1><p>' + esc(sup.name) + ' · here\'s your business today, ' + U.fmtDate(T) + '.</p></div><div class="row wrap">' + (canProd ? '<a class="btn" href="' + url('supplier/product-form.html') + '">' + I('plus') + 'Add product</a>' : '') + '<a class="btn btn-primary" href="' + url('supplier/requests.html') + '">' + I('list') + 'Review requests' + (pend.length ? ' (' + pend.length + ')' : '') + '</a></div></div>' +
      (pend.some(r => conflictsFor(r).length) ? '<div class="alert alert-warn mb-2">' + I('alert') + '<div><b>Inventory conflict:</b> ' + pend.filter(r => conflictsFor(r).length).map(r => '<a href="' + url('supplier/request.html', { id: r.id }) + '">' + r.id + '</a>').join(', ') + ' request more than you have available. Review before accepting.</div></div>' : '') +
      '<div class="stats">' +
      UI.stat('Listed rental items', prods.filter(p => p.status === 'published').length, prods.length + ' total incl. inactive', 'box', 'purple', url('supplier/products.html')) +
      UI.stat('Total stock', U.sum(snap, b => b.total).toLocaleString(), 'units across all items', 'layers', 'sky', url('supplier/inventory.html')) +
      UI.stat('Available today', U.sum(snap, b => b.available).toLocaleString(), 'units free to rent', 'check', 'teal', url('supplier/inventory.html')) +
      UI.stat('Reserved today', U.sum(snap, b => b.reserved).toLocaleString(), 'from accepted rentals', 'calendar', 'pink', url('supplier/calendar.html')) +
      UI.stat('Maintenance / damaged', U.sum(snap, b => b.maintenance + b.damaged + b.missing + b.setaside), U.sum(snap, b => b.maintenance) + ' in maintenance', 'tool', 'gold', url('supplier/inventory.html')) +
      UI.stat('Pending requests', pend.length, 'awaiting your review', 'clock', 'gold', url('supplier/requests.html')) +
      UI.stat('Accepted reservations', reqs.filter(r => ['accepted', 'in_progress', 'ready_pickup', 'out_delivery'].includes(r.status)).length, 'upcoming', 'calendar', 'sky', url('supplier/requests.html', { tab: 'upcoming' })) +
      UI.stat('Ongoing rentals', reqs.filter(r => ['ongoing', 'return_pending', 'inspection'].includes(r.status)).length, 'with customers / returning', 'truck', 'pink', url('supplier/schedule.html')) +
      UI.stat('Completed', reqs.filter(r => r.status === 'completed').length, 'transactions', 'check', 'teal') +
      (money ? UI.stat('Pending payments', pendingPay.length, U.moneyShort(U.sum(pendingPay, p => p.amount)) + ' awaiting verification', 'card', 'gold', url('supplier/payments.html', { tab: 'verify' })) +
      UI.stat('Partially paid', fins.filter(x => x.f.status === 'Partially Paid').length, '', 'cash', 'sky', url('supplier/payments.html')) +
      UI.stat('Fully paid', fins.filter(x => x.f.status === 'Fully Paid').length, '', 'check', 'teal', url('supplier/payments.html')) +
      UI.stat('Overdue payments', fins.filter(x => x.f.isOverdue).length, U.moneyShort(U.sum(fins.filter(x => x.f.isOverdue), x => x.f.overdueAmount)) + ' outstanding', 'alert', 'red', url('supplier/payments.html', { tab: 'overdue' })) +
      UI.stat('Revenue this month', U.moneyShort(thisMonth), 'verified rental payments', 'chart', 'purple', url('supplier/reports.html')) : '') + '</div>' +
      '<div class="grid grid-2 mt-3"><div class="card"><div class="card-head"><h3>Monthly rental transactions</h3><span class="small muted">Requests received</span></div><div id="c1"></div></div>' + (money ? '<div class="card"><div class="card-head"><h3>Revenue trend</h3><span class="small muted">Verified rental payments</span></div><div id="c2"></div></div>' : '') + '' +
      '<div class="card"><div class="card-head"><h3>Most rented products</h3><span class="small muted">Units booked (all time)</span></div><div id="c3"></div></div><div class="card"><div class="card-head"><h3>Reservation status</h3></div><div id="c4"></div></div>' +
      (money ? '' + (money ? '<div class="card"><div class="card-head"><h3>Category performance</h3><span class="small muted">Rental income by category</span></div><div id="c5"></div></div>' : '') + '' : '') +
      '<div class="card"><div class="card-head"><h3>Upcoming rental schedule</h3><a class="small strong" href="' + url('supplier/schedule.html') + '">Open schedule</a></div>' + (upcoming.length ? upcoming.slice(0, 6).map(r => '<a class="row between" href="' + url('supplier/request.html', { id: r.id }) + '" style="padding:10px 0;border-bottom:1px solid var(--line);color:inherit;text-decoration:none"><div><b>' + U.fmtDate(r.start, { year: undefined }) + '</b> · ' + esc(r.eventName) + '<div class="small muted">' + r.id + ' · ' + esc(Store.user(r.customerId).name) + ' · ' + (r.fulfillment === 'delivery' ? 'Delivery' : 'Pickup') + '</div></div>' + UI.statusBadge(r.status) + '</a>').join('') : '<p class="muted">No upcoming rentals.</p>') + '</div></div>';
    const ym = r => r.createdAt.slice(0, 7);
    Charts.bars($('#c1'), months.map(m => ({ label: m.label, value: reqs.filter(r => ym(r) === m.key).length })), { color: '#7C3AED', label: 'Monthly requests' });
    if ($('#c2')) Charts.line($('#c2'), months.map(m => ({ label: m.label, value: revBy(m.key) })), { money: true, color: '#E11D74', label: 'Revenue' });
    const units = {}; reqs.filter(r => !['declined', 'cancelled', 'pending'].includes(r.status)).forEach(r => { Object.values(Inventory.demandMap(r.lines)).forEach(m => Object.entries(m).forEach(([pid, q]) => { units[pid] = (units[pid] || 0) + q; })); });
    Charts.hbars($('#c3'), Object.entries(units).map(([pid, v]) => ({ label: Store.product(pid).name, value: v })).sort((a, b) => b.value - a.value).slice(0, 6), { color: '#E11D74' });
    const grp = [['Pending', ['pending']], ['Upcoming', ['accepted', 'in_progress', 'ready_pickup', 'out_delivery']], ['Ongoing / returning', ['ongoing', 'return_pending', 'inspection']], ['Completed', ['completed']], ['Declined / cancelled', ['declined', 'cancelled']]];
    Charts.donut($('#c4'), grp.map(([l, st]) => ({ label: l, value: reqs.filter(r => st.includes(r.status)).length })), { center: 'requests' });
    const catRev = {}; reqs.filter(r => !['declined', 'cancelled', 'pending'].includes(r.status)).forEach(r => r.pricing.lines.forEach(l => { const cats = l.type === 'package' ? ['Packages'] : [Store.category(Store.product(l.refId).categoryId).name]; catRev[cats[0]] = (catRev[cats[0]] || 0) + l.total; }));
    if ($('#c5')) Charts.hbars($('#c5'), Object.entries(catRev).map(([k, v]) => ({ label: k, value: v })).sort((a, b) => b.value - a.value), { money: true, color: '#7C3AED' });
  };

  /* ================= REQUESTS (centralized) ================= */
  SP.requests = function (ctx) {
    const groups = { pending: ['pending'], upcoming: ['accepted', 'in_progress', 'ready_pickup', 'out_delivery'], active: ['ongoing', 'return_pending', 'inspection'], completed: ['completed'], closed: ['declined', 'cancelled'], all: null };
    let tab = ctx.params.tab || 'pending', q = '';
    ctx.el.innerHTML = '<div class="page-head"><div><h1>Rental Requests</h1><p>Review, accept or decline requests. Acceptance re-checks stock for every date.</p></div><input class="input input-sm" id="q" placeholder="Search no., customer, event" style="width:240px" aria-label="Search"></div><div id="tb"></div><div class="card pad-0" id="lst"></div>';
    const draw = () => {
      const reqs = myReqs(ctx).sort((a, b) => tab === 'pending' || tab === 'upcoming' ? a.start.localeCompare(b.start) : b.createdAt.localeCompare(a.createdAt));
      $('#tb').innerHTML = UI.tabs([['pending', 'Pending'], ['upcoming', 'Accepted / Upcoming'], ['active', 'Ongoing & Returns'], ['completed', 'Completed'], ['closed', 'Declined / Cancelled'], ['all', 'All']].map(([k, l]) => ({ key: k, label: l, count: reqs.filter(r => !groups[k] || groups[k].includes(r.status)).length })), tab);
      $$('#tb [data-tab]').forEach(t => t.onclick = () => { tab = t.dataset.tab; draw(); });
      const list = reqs.filter(r => !groups[tab] || groups[tab].includes(r.status)).filter(r => !q || (r.id + ' ' + r.eventName + ' ' + Store.user(r.customerId).name).toLowerCase().includes(q));
      $('#lst').innerHTML = UI.table([
        { label: 'Request', render: r => '<a class="strong" href="' + url('supplier/request.html', { id: r.id }) + '">' + r.id + '</a><div class="small muted">' + esc(r.eventName) + '</div>' },
        { label: 'Customer', render: r => esc(Store.user(r.customerId).name) },
        { label: 'Products', render: r => '<div class="small" style="max-width:260px">' + reqItems(r) + '</div>' },
        { label: 'Rental dates', render: r => U.fmtRange(r.start, r.end) + '<div class="small muted">' + U.range(r.start, r.end).length + ' day(s) · ' + reqQty(r) + ' units</div>' },
        { label: 'Amount', cls: 'num', render: r => '<b>' + U.money(r.pricing.total) + '</b>' + (r.destinations && r.destinations.length > 1 ? '<div class="small muted">' + r.destinations.length + ' locations</div>' : '') },
        { label: 'Payment', render: r => '<div class="small">' + Finance.PLAN_LABEL[r.plan] + '<br>' + Finance.METHOD_LABEL[r.method] + (r.installmentPlan && r.installmentPlan.status === 'proposed' ? '<br><span class="badge b-gold">Schedule to review</span>' : '') + '</div>' },
        { label: 'Submitted', render: r => '<span class="small">' + U.timeAgo(r.createdAt) + '</span>' },
        { label: 'Status', render: r => { const c = conflictsFor(r); return UI.statusBadge(r.status) + (c.length ? '<div><span class="badge b-red mt-1">Stock conflict</span></div>' : r.status !== 'pending' && !['declined', 'cancelled'].includes(r.status) ? '<div class="mt-1">' + UI.payBadge(Finance.summary(r).status) + '</div>' : ''); } },
        { label: '', render: r => '<a class="btn btn-sm ' + (r.status === 'pending' ? 'btn-primary' : '') + '" href="' + url('supplier/request.html', { id: r.id }) + '">' + (r.status === 'pending' ? 'Review' : 'Open') + '</a>' }
      ], list, { emptyText: 'No requests in this tab.' });
    };
    $('#q').oninput = e => { q = e.target.value.toLowerCase(); draw(); };
    draw();
  };

  /* ================= REQUEST DETAILS & WORKFLOW ================= */
  SP.request = function (ctx) {
    const r = ownReq(ctx, ctx.params.id);
    if (!r) { ctx.el.innerHTML = UI.empty('🔒', 'Request not found', 'This request does not belong to your shop.', '<a class="btn" href="' + url('supplier/requests.html') + '">All requests</a>'); return; }
    const can = p => Auth.orgCan(p, ctx.session.user);
    const draw = () => {
      const c = Store.user(r.customerId); const f = Finance.summary(r);
      const confl = conflictsFor(r);
      const next = (Services.FLOW[r.status] || []).filter(st => !(st === 'ready_pickup' && r.fulfillment !== 'pickup') && !(st === 'out_delivery' && r.fulfillment !== 'delivery'));
      const custHist = Store.where('requests', x => x.customerId === c.id);
      // date- and time-based availability for every product (and every allocated inventory location)
      const chk = Inventory.check(r.lines, { excludeRequestId: r.id });
      const showAvail = ['pending', 'accepted', 'in_progress'].includes(r.status);
      const locs = Inventory.locationsOf(r.supplierId);
      const canAlloc = ['pending', 'accepted', 'in_progress'].includes(r.status) && (can('orders.manage') || can('inventory.manage')) && locs.length > 1;
      const ip = r.installmentPlan;
      const pendPays = Finance.paymentsFor(r.id).filter(p => p.status === 'pending');
      const finOK = Auth.canFinance(r.supplierId, 'payments.verify');
      ctx.el.innerHTML = '<div class="crumbs"><a href="' + url('supplier/requests.html') + '">Rental Requests</a> / ' + r.id + '</div><div class="page-head"><div><h1>' + esc(r.eventName) + '</h1><p>' + r.id + ' · ' + esc(r.eventType) + ' · event ' + U.fmtDate(r.eventDate) + ' · submitted ' + U.fmtDateTime(r.createdAt) + '</p></div><div class="row wrap">' + UI.statusBadge(r.status) + (r.status !== 'pending' ? UI.payBadge(f.status) : '') + UI.planBadge(r.plan) + '</div></div>' +
        '<div class="card mb-2">' + Sh().progress(r) + '</div>' +
        '<div class="card mb-2" id="actions"></div>' +
        (f.isOverdue ? '<div class="alert alert-danger mb-2">' + I('alert') + '<div><b>Overdue payment:</b> ' + U.money(f.overdueAmount) + ' outstanding. Review with the customer and apply your cancellation policy if needed — the rental is never cancelled automatically.</div></div>' : '') +
        '<div class="grid grid-side"><div class="stack">' +
        (showAvail ? '<div class="card"><div class="card-head"><h3>Availability check (date & time)</h3>' + (r.status === 'pending' ? (confl.length ? '<span class="badge b-red">Cannot accept: insufficient stock</span>' : '<span class="badge b-green">All dates and times can be accommodated</span>') : '<span class="badge b-sky">Reserved</span>') + '</div><p class="small muted">Available = total − the highest number of units already booked during an overlapping time (including your preparation and recovery time) − damaged, missing, written-off, maintenance and set-aside units. Bookings at non-overlapping times share the same units.</p>' +
          UI.table([{ label: 'Date', render: x => U.fmtDay(x.date) }, { label: 'Item', render: x => esc(Store.product(x.productId).name) + (x.locationId ? '<div class="small muted">at ' + esc(Services.locName(r.supplierId, x.locationId)) + '</div>' : '') }, { label: 'Requested (peak)', cls: 'num', render: x => '<b>' + x.requested + '</b>' }, { label: 'Available', cls: 'num', render: x => x.available }, { label: 'Other pending', cls: 'num', render: x => { const n = x.locationId ? 0 : Inventory.pendingOn(x.productId, x.date, r.id); return n ? '<span style="color:#B45309">' + n + '</span>' : '0'; } }, { label: 'Result', render: x => x.ok ? '<span class="badge b-green">OK</span>' : '<span class="badge b-red">Short by ' + Math.max(1, x.requested - x.available) + '</span>' }], chk.rows, { rowAttr: x => !x.ok ? 'class="row-bad"' : '' }) + '</div>' : '') +
        (locs.length ? '<div class="card"><div class="card-head"><h3>Inventory allocation</h3><span class="badge ' + ((r.allocation || {}).status === 'approved' ? 'b-green' : 'b-gold') + '">' + ((r.allocation || {}).status === 'approved' ? 'Approved' : 'Proposed — review before accepting') + '</span></div><p class="small muted">Each line uses stock from one inventory location. PartyRent proposed the sources below; ' + (canAlloc ? 'change them if another location is closer or has the stock.' : 'they can be changed before the items are released.') + '</p>' +
          UI.table([{ label: 'Item', render: l => '<b>' + esc(Services.itemName(l)) + '</b><div class="small muted">' + esc(UI.timeLabel(l)) + '</div>' }, { label: 'Deliver to', render: l => { const d = (r.destinations || []).find(x => x.id === l.destId); return d ? esc(d.label) : (r.fulfillment === 'pickup' ? 'Pickup' : '—'); } }, { label: 'Qty / dates', render: l => Math.max.apply(null, Object.values(l.days).map(Number)) + '× · ' + U.fmtRange(Object.keys(l.days).sort()[0], Object.keys(l.days).sort().slice(-1)[0]) }, { label: 'Inventory source', render: l => canAlloc ? '<select class="input input-sm" data-src="' + l.id + '" aria-label="Inventory source">' + locs.map(loc => { const pid = l.type === 'package' ? null : l.refId; const d0 = Object.keys(l.days).sort()[0]; const av = pid ? Inventory.availableAt(pid, loc.id, d0, { excludeRequestId: r.id, window: Inventory.lineWindow(l, d0) }) : null; return '<option value="' + loc.id + '"' + (loc.id === l.sourceId ? ' selected' : '') + '>' + esc(loc.name) + (av != null ? ' (' + av + ' free)' : '') + '</option>'; }).join('') + '</select>' : esc(Services.locName(r.supplierId, l.sourceId)) }], r.lines) + '</div>' : '') +
        (r.plan === 'installment' ? '<div class="card"><div class="card-head"><h3>Installment schedule</h3>' + (ip ? '<span class="badge ' + ({ approved: 'b-green', proposed: 'b-gold', rejected: 'b-red' }[ip.status]) + '">' + ({ approved: 'Approved', proposed: 'Proposed by customer', rejected: 'Rejected' }[ip.status]) + '</span>' : '') + '</div>' + (ip ? UI.table([{ label: 'Installment', render: x => 'Installment ' + x.n + ' of ' + ip.items.length }, { label: 'Due', render: x => U.fmtDate(x.due) + (x.due > r.eventDate ? ' <span class="badge b-red">after event</span>' : '') }, { label: 'Amount', cls: 'num', render: x => '<b>' + U.money(x.amount) + '</b>' }], ip.items.map((x, i) => Object.assign({ n: i + 1 }, x))) + '<p class="small muted mt-1">Installment balance ' + U.money(r.pricing.finalBalance) + ' (after the ' + r.pricing.terms.resPct + '% reservation fee and ' + r.pricing.terms.downPct + '% down payment) · last allowed due date ' + U.fmtDate(r.eventDate) + '.</p>' + (ip.status === 'rejected' ? '<div class="alert alert-danger">' + I('x') + '<div class="small">Rejected: ' + esc(ip.reason) + ' — waiting for the customer to propose a new schedule.</div></div>' : '') + (ip.status === 'proposed' && can('orders.manage') && !['declined', 'cancelled', 'completed'].includes(r.status) ? '<div class="btn-group mt-1"><button class="btn btn-danger btn-sm" id="ipRej">' + I('x') + 'Reject schedule</button><button class="btn btn-success btn-sm" id="ipOk">' + I('check') + 'Approve schedule</button></div>' : '') : '<p class="muted small">The customer has not proposed a schedule yet.</p>') + '</div>' : '') +
        '<div class="card"><h3>Requested items, times & daily quantities</h3>' + Sh().linesTable(r, { showSource: true }) + '</div>' +
        '<div class="card"><div class="card-head"><h3>Payments</h3>' + (Finance.ACTIVE.includes(r.status) && Auth.canFinance(r.supplierId, 'payments.record') ? '<button class="btn btn-sm" id="recPay">' + I('cash') + 'Record payment</button>' : '') + '</div>' + (pendPays.length ? '<div class="alert alert-warn mb-1">' + I('clock') + '<div class="grow">' + pendPays.length + ' payment(s) awaiting verification. ' + (finOK ? pendPays.map(p => '<button class="btn btn-xs btn-primary" data-review="' + p.id + '">Review ' + U.money(p.amount) + '</button>').join(' ') : 'Your Cashier or Organization Admin verifies them.') + '</div></div>' : '') + Sh().paymentHistory(r) + '<p class="small muted mt-1 mb-0">Only verified payments reduce the balance. Duplicate reference numbers and amounts above the outstanding balance are blocked.</p></div>' +
        (r.inspection ? Sh().inspectionReport(r) : '') +
        '<div class="card"><h3>Activity</h3>' + Sh().timeline(r) + '</div></div>' +
        '<aside class="stack"><div class="card"><h3>Customer</h3><div class="row mb-1"><span class="avatar">' + U.initials(c.name) + '</span><div><b>' + esc(c.name) + '</b><div class="small muted">' + custHist.length + ' request(s) on PartyRent · ' + custHist.filter(x => x.status === 'completed').length + ' completed</div></div></div><dl class="kv"><dt>Contact</dt><dd>' + esc(r.contactName || c.name) + '<br>' + esc(r.contactPhone || c.phone) + '<br>' + esc(c.email) + '</dd><dt>Payment</dt><dd>' + Finance.PLAN_LABEL[r.plan] + ' · ' + Finance.METHOD_LABEL[r.method] + '</dd></dl>' + (r.instructions ? '<div class="alert alert-info mt-1">' + I('message') + '<div class="small"><b>Instructions:</b> ' + esc(r.instructions) + '</div></div>' : '') + '</div>' +
        '<div class="card"><h3>' + (r.fulfillment === 'delivery' ? (r.destinations.length > 1 ? r.destinations.length + ' delivery locations' : 'Delivery location') : 'Pickup') + '</h3>' + Sh().destinations(r) + '</div>' +
        '<div class="card">' + Sh().paymentSummary(r) + '</div>' +
        '<div class="card"><h3>Supplier notes</h3><p class="small">' + (r.supplierNotes ? esc(r.supplierNotes) : '<span class="muted">No notes yet. Notes are visible to the customer.</span>') + '</p>' + (can('orders.manage') ? '<button class="btn btn-sm" id="noteBtn">' + I('edit') + 'Edit notes</button>' : '') + '</div>' +
        (r.fulfillmentLog && r.fulfillmentLog.releaseDate ? '<div class="card"><h3>Release & return log</h3><dl class="kv"><dt>Released</dt><dd>' + U.fmtDate(r.fulfillmentLog.releaseDate) + '</dd><dt>Quantity</dt><dd>' + esc(r.fulfillmentLog.releaseQty || '') + '</dd><dt>Received by</dt><dd>' + esc(r.fulfillmentLog.receivedBy) + '</dd>' + (r.fulfillmentLog.returnDate ? '<dt>Returned</dt><dd>' + U.fmtDate(r.fulfillmentLog.returnDate) + '</dd><dt>Returned qty</dt><dd>' + esc(r.fulfillmentLog.returnedQty || '') + '</dd>' : '') + '</dl></div>' : '') + '</aside></div>';
      // actions
      const A = $('#actions');
      const canAct = st => st === 'inspection' ? can('returns.inspect') : (can('fulfillment.update') || can('orders.manage'));
      let html = '<div class="row wrap between"><div><b>Next step</b><div class="small muted">';
      if (r.status === 'pending') html += 'Check availability, the inventory allocation' + (r.plan === 'installment' ? ' and the installment schedule' : '') + ', then accept or decline.</div></div>' + (can('orders.manage') ? '<div class="btn-group"><button class="btn btn-danger" id="decl">' + I('x') + 'Decline</button><button class="btn btn-success" id="acc"' + (confl.length ? ' title="Not enough stock"' : '') + '>' + I('check') + 'Accept request</button></div>' : '<span class="small muted">Only the Organization Admin can accept or decline.</span>') + '</div>';
      else if (next.length) html += { accepted: 'Prepare the items once payments are in order.', in_progress: r.fulfillment === 'delivery' ? 'Send the items out for delivery.' : 'Notify the customer that items are ready for pickup.', ready_pickup: 'Record who picked up the items.', out_delivery: 'Record who received the delivery.', ongoing: 'Mark the rental for return after the event (' + U.fmtDate(r.end) + ').', return_pending: 'Count the returned items and assess any damage or loss.', inspection: 'Settle the security deposit and complete the rental.' }[r.status] + '</div></div><div class="btn-group">' + (r.status === 'inspection' && (can('payments.record') || can('orders.manage')) ? '<button class="btn" id="settle"' + (r.inspection && r.inspection.settlement !== 'pending' && Finance.summary(r).depositHeld <= 0 ? ' disabled' : '') + '>' + I('shield') + 'Settle deposit</button>' : '') + next.filter(canAct).map(st => '<button class="btn btn-primary" data-adv="' + st + '">' + esc(Services.ACTION_LABEL[st]) + '</button>').join('') + '</div></div>';
      else html += 'No further action. This request is ' + Services.statusLabel(r.status).toLowerCase() + '.</div></div></div>';
      if (r.status === 'inspection') { const cl = Services.completionChecklist(r); html += '<div class="row wrap mt-2 gap-sm">' + cl.map(x => '<span class="badge ' + (x.ok ? 'b-green' : 'b-gray') + '">' + (x.ok ? '✓ ' : '○ ') + esc(x.label) + (x.detail ? ' · ' + esc(x.detail) : '') + '</span>').join('') + '</div>'; }
      A.innerHTML = html;
      const acc = $('#acc'); if (acc) acc.onclick = () => acceptFlow(r, draw);
      const dec = $('#decl'); if (dec) dec.onclick = async () => { const reason = await UI.prompt({ title: 'Decline ' + r.id + '?', message: 'The customer will be notified. The request record is kept.', label: 'Reason (shown to the customer)', textarea: true, required: true, confirmText: 'Decline request', danger: true }); if (reason == null) return; const res = Services.declineRequest(r.id, reason); if (!res.ok) return UI.toast(res.error, 'error'); UI.toast('Request declined.', 'success'); draw(); };
      $$('[data-adv]').forEach(b => b.onclick = () => advanceFlow(r, b.dataset.adv, draw));
      const st = $('#settle'); if (st) st.onclick = () => settleFlow(r, draw);
      const nb = $('#noteBtn'); if (nb) nb.onclick = async () => { const v = await UI.prompt({ title: 'Supplier notes', label: 'Notes for this rental (visible to customer)', textarea: true, value: r.supplierNotes, confirmText: 'Save notes' }); if (v == null) return; r.supplierNotes = v; Store.save(); draw(); };
      const rp = $('#recPay'); if (rp) rp.onclick = () => recordCash(r, draw);
      $$('[data-review]').forEach(b => b.onclick = () => Sh().reviewPayment(Store.get('payments', b.dataset.review), draw));
      $$('[data-src]').forEach(sel => sel.onchange = () => { const res = Services.setLineSource(r.id, sel.dataset.src, sel.value); if (!res.ok) UI.toast(res.error, 'error'); else UI.toast('Inventory source updated.', 'success'); draw(); });
      const ipOk = $('#ipOk'); if (ipOk) ipOk.onclick = async () => { if (!await UI.confirm({ title: 'Approve installment schedule?', message: ip.items.length + ' payments, the last one due ' + U.fmtDate(ip.items[ip.items.length - 1].due) + '. The customer will be notified.', confirmText: 'Approve' })) return; const res = Services.reviewInstallmentPlan(r.id, true); if (!res.ok) return UI.toast(res.error, 'error'); UI.toast('Installment schedule approved.', 'success'); draw(); };
      const ipRej = $('#ipRej'); if (ipRej) ipRej.onclick = async () => { const reason = await UI.prompt({ title: 'Reject installment schedule?', label: 'Reason (the customer will propose a new schedule)', textarea: true, required: true, confirmText: 'Reject', danger: true }); if (reason == null) return; const res = Services.reviewInstallmentPlan(r.id, false, reason); if (!res.ok) return UI.toast(res.error, 'error'); UI.toast('Schedule rejected. Customer notified.', 'success'); draw(); };
    };
    draw();
  };

  function acceptFlow(r, done) {
    const rev = Services.acceptReview(r.id);
    const fake = Object.assign({}, r, { acceptedAt: U.today(), status: 'accepted' });
    const sched = Finance.schedule(fake);
    const m = UI.modal({ title: 'Accept ' + r.id, body:
      '<div class="stack-sm"><div class="row">' + (rev.check.ok ? '✅' : '❌') + '<b>1. Inventory re-checked for every date, time and location</b></div>' + (rev.check.ok ? '<div class="small muted" style="padding-left:28px">All quantities fit within available stock at the allocated locations.</div>' : '<div class="alert alert-danger">' + I('alert') + '<div>' + rev.check.bad.map(b => U.fmtDate(b.date) + ': ' + esc(Store.product(b.productId).name) + (b.locationId ? ' at ' + esc(Services.locName(r.supplierId, b.locationId)) : '') + ' needs ' + b.requested + ', only ' + b.available + ' available').join('<br>') + '<br><b>Acceptance is blocked to prevent double-booking.</b> Change the allocation, decline, or ask the customer to change quantities or times.</div></div>') +
      '<div class="row">' + (rev.priceChanged ? '⚠️' : '✅') + '<b>2. Rental Charges validated</b></div><div class="small muted" style="padding-left:28px">' + (rev.priceChanged ? 'Your current prices total ' + U.money(rev.fresh.total) + '; the customer was quoted ' + U.money(r.pricing.total) + '. The quoted price will be honored.' : 'Quoted total ' + U.money(r.pricing.total) + ' matches your current prices.') + '</div>' +
      '<div class="row">' + (rev.policyIssues.length ? '⚠️' : '✅') + '<b>3. Payment plan confirmed</b></div><div class="small muted" style="padding-left:28px">' + (rev.policyIssues.length ? esc(rev.policyIssues.join(' ')) : Finance.PLAN_LABEL[r.plan] + ' via ' + Finance.METHOD_LABEL[r.method] + '. Security deposit ' + U.money(r.pricing.deposit) + '.') + '</div>' +
      (rev.durationNotes.length ? '<div class="alert alert-warn">' + I('info') + '<div class="small">' + rev.durationNotes.map(d => esc(d.name) + ' is booked for ' + d.span + ' days; your current limit is ' + d.max + '. The request was valid when submitted, so you may still accept or decline it.').join('<br>') + '</div></div>' : '') +
      '<div class="row">📦<b>4. Inventory allocation approved</b></div><div class="small muted" style="padding-left:28px">' + r.lines.map(l => esc(Services.itemName(l)) + ' → ' + esc(Services.locName(r.supplierId, l.sourceId))).join('<br>') + '</div>' +
      '<div class="row">📅<b>5. Payment deadlines to be generated</b></div><div style="padding-left:28px">' + sched.map(x => '<div class="sum-line small"><span>' + esc(x.label) + ' · due ' + U.fmtDate(x.due) + '</span><b>' + U.money(x.amount) + '</b></div>').join('') + '</div></div>' +
      '<div class="field mt-2"><label>Note to customer (optional)</label><textarea class="input" id="an" placeholder="e.g. We will deliver at 8 AM.">' + esc(r.supplierNotes || '') + '</textarea></div>',
      foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-success" id="doAcc"' + (rev.canAccept ? '' : ' disabled') + '>' + I('check') + 'Accept & reserve stock</button>' });
    m.el.querySelector('#doAcc').onclick = () => {
      const res = Services.acceptRequest(r.id, m.el.querySelector('#an').value.trim());
      if (!res.ok) { UI.toast(res.error, 'error'); return; }
      m.close(); UI.toast(r.id + ' accepted. Stock reserved and customer notified.', 'success'); done();
    };
  }

  function advanceFlow(r, to, done) {
    if (to === 'ongoing') {
      const summary = r.lines.map(l => { const d = Object.keys(l.days).sort()[0]; return l.days[d] + '× ' + Services.itemName(l); }).join(', ');
      const m = UI.modal({ title: 'Record release to customer', body: '<form id="rf" novalidate><div class="form-grid"><div class="field"><label>Release date</label><input class="input" type="date" name="releaseDate" value="' + U.today() + '" required></div><div class="field"><label>Person receiving the items</label><input class="input" name="receivedBy" required value="' + esc(r.contactName || Store.user(r.customerId).name) + '"></div></div><div class="field"><label>Released quantity</label><textarea class="input" name="releaseQty" required>' + esc(summary) + '</textarea><div class="hint">First-day quantities shown. For multi-day rentals with changing quantities, note any later drop-offs.</div></div></form>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Confirm release</button>' });
      m.el.querySelector('#ok').onclick = () => { const f = m.el.querySelector('#rf'); if (!UI.validate(f)) return; const res = Services.advance(r.id, 'ongoing', UI.formData(f)); if (!res.ok) return UI.toast(res.error, 'error'); m.close(); UI.toast('Release recorded. Rental is now ongoing.', 'success'); done(); };
      return;
    }
    if (to === 'inspection') return inspectFlow(r, done);
    if (to === 'completed') {
      const res = Services.completeRental(r.id);
      if (!res.ok) return UI.toast(res.error, 'error');
      UI.toast('Rental completed. History is preserved.', 'success'); return done();
    }
    const f = Finance.summary(r);
    const warn = to === 'in_progress' && f.paidRental <= 0 ? '<div class="alert alert-warn mt-1">' + I('alert') + '<div>No verified payment yet (' + f.status + '). You can still prepare, but consider waiting for the first payment.</div></div>' : '';
    UI.confirm({ title: Services.ACTION_LABEL[to] + '?', html: 'Update <b>' + r.id + '</b> to <b>' + Services.statusLabel(to) + '</b>. The customer will be notified.' + warn, confirmText: 'Update status' }).then(ok => { if (!ok) return; const res = Services.advance(r.id, to); if (!res.ok) return UI.toast(res.error, 'error'); UI.toast('Status updated to ' + Services.statusLabel(to) + '.', 'success'); done(); });
  }

  /** Return inspection with the supplier's damage policy: count returns, classify damage, review, then confirm. */
  function inspectFlow(r, done) {
    const sup = Store.supplier(r.supplierId);
    const rented = Services.rentedUnits(r);
    const pids = Object.keys(rented);
    const photos = [];
    const C = Services.CONDITIONS;
    const m = UI.modal({ title: 'Return inspection · ' + r.id, size: 'lg', body: '<p class="small muted">Count the returned units and classify any damage. Compensation is calculated automatically from <b>your damage policy</b>: product value × compensation % × affected quantity. Units not returned count as <b>Lost or Not Returned</b>. Nothing is charged until you review and confirm.</p><form id="inf" novalidate><div class="field"><label>Return date</label><input class="input" type="date" name="returnDate" value="' + U.today() + '" required style="max-width:200px"></div>' +
      pids.map(pid => { const p = Store.product(pid); const rt = Services.damageRates(sup, p); const pc = (o, lbl) => '<span class="badge ' + (o.enabled ? 'b-gray' : 'b-red') + ' plain">' + lbl + ': ' + (o.enabled ? o.pct + '%' : 'off') + '</span>'; return '<div class="card card-flat mb-1" data-pid="' + pid + '" style="padding:14px"><div class="row between wrap mb-1"><div><b>' + esc(p.name) + '</b><div class="small muted">Rented: ' + rented[pid] + ' · condition before rental: ' + esc(C[p.condition] || p.condition) + ' · product value ' + U.money(p.value || 0) + '</div></div><div class="row wrap gap-sm">' + pc(rt.repairable, 'Repairable') + pc(rt.nonRepairable, 'Non-repairable') + pc(rt.lost, 'Lost (' + (C[p.condition] || '') + ')') + (rt.source === 'category' ? '<span class="badge b-purple plain">category rule</span>' : '') + '</div></div>' +
        '<div class="form-grid" style="grid-template-columns:repeat(4,minmax(0,1fr))"><div class="field"><label class="small">Returned</label><input class="input input-sm" type="number" min="0" max="' + rented[pid] + '" name="returned" value="' + rented[pid] + '"></div><div class="field"><label class="small">Repairable damage</label><input class="input input-sm" type="number" min="0" name="repairable" value="0"></div><div class="field"><label class="small">Non-repairable damage</label><input class="input input-sm" type="number" min="0" name="nonRepairable" value="0"></div><div class="field"><label class="small">Lost / not returned</label><input class="input input-sm" type="number" name="lost" value="0" readonly tabindex="-1" aria-label="Lost units (rented minus returned)"></div></div>' +
        '<div class="field"><label class="small">Description of the damage or loss</label><textarea class="input" name="description" rows="2" placeholder="e.g. Two chairs with cracked legs"></textarea></div><div class="row between small"><span class="muted" data-calc></span><b data-amt>₱0.00</b></div><div class="error-text" data-err></div></div>'; }).join('') +
      '<div class="field"><label>Inspection notes</label><textarea class="input" name="notes" placeholder="General notes for the customer…"></textarea></div><div class="field"><label>Photo evidence</label><label class="upload-box" for="ph">' + I('upload') + '<div class="small">Upload photos of damaged items (optional)</div></label><input type="file" id="ph" accept="image/*" multiple hidden><div class="thumbs" id="phv"></div></div><div class="sum-line total"><span>Total compensation</span><span id="compT">₱0.00</span></div></form>',
      foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Review assessment</button>' });
    const f = m.el.querySelector('#inf');
    const read = () => $$('[data-pid]', f).map(c => { const g = n => c.querySelector('[name=' + n + ']').value; return { productId: c.dataset.pid, returned: g('returned'), repairable: g('repairable'), nonRepairable: g('nonRepairable'), description: g('description') }; });
    const calc = () => {
      const as = Services.assessDamage(r, read());
      $$('[data-pid]', f).forEach(c => { const it = as.items.find(i => i.productId === c.dataset.pid); c.querySelector('[name=lost]').value = it.lost; c.querySelector('[data-amt]').textContent = U.money(it.total); c.querySelector('[data-calc]').textContent = [it.repairable ? it.repairable + ' × ' + U.money(it.value) + ' × ' + it.pcts.repairable + '%' : '', it.nonRepairable ? it.nonRepairable + ' × ' + U.money(it.value) + ' × ' + it.pcts.nonRepairable + '%' : '', it.lost ? it.lost + ' lost × ' + U.money(it.value) + ' × ' + it.pcts.lost + '%' : ''].filter(Boolean).join(' + ') || 'No damage or loss'; const err = c.querySelector('[data-err]'); const name = Store.product(it.productId).name; const msg = as.errors.filter(e => e.startsWith(name + ':')).join(' '); err.textContent = msg; err.style.display = msg ? 'block' : 'none'; });
      m.el.querySelector('#compT').textContent = U.money(as.total);
      return as;
    };
    f.addEventListener('input', calc); calc();
    m.el.querySelector('#ph').onchange = async e => { for (const file of Array.from(e.target.files).slice(0, 4)) { try { photos.push(await U.readImage(file, 600)); } catch (err) { UI.toast(err.message, 'error'); } } m.el.querySelector('#phv').innerHTML = photos.map(p => '<img src="' + p + '" alt="Evidence">').join(''); };
    m.el.querySelector('#ok').onclick = async () => {
      if (!UI.validate(f)) return;
      const as = calc();
      if (!as.ok) return UI.toast(as.errors[0], 'error');
      const affected = as.items.filter(i => i.repairable || i.nonRepairable || i.lost);
      const html = (affected.length ? UI.table([{ label: 'Product', render: i => esc(Store.product(i.productId).name) }, { label: 'Repairable', cls: 'num', render: i => i.repairable ? i.repairable + ' × ' + i.pcts.repairable + '%' : '—' }, { label: 'Non-repairable', cls: 'num', render: i => i.nonRepairable ? i.nonRepairable + ' × ' + i.pcts.nonRepairable + '%' : '—' }, { label: 'Lost', cls: 'num', render: i => i.lost ? i.lost + ' × ' + i.pcts.lost + '%' : '—' }, { label: 'Compensation', cls: 'num', render: i => '<b>' + U.money(i.total) + '</b>' }], affected) : '<p>All items were returned in good condition — no compensation.</p>') +
        '<div class="sum-line total"><span>Total compensation</span><span>' + U.money(as.total) + '</span></div><ul class="small muted"><li>Repairable units stay unavailable until you mark them repaired.</li><li>Non-repairable and lost units are removed from usable inventory.</li><li>The customer sees the breakdown, explanation and photos. The charge is kept separate from the rental fee and can only be recorded once.</li></ul>';
      if (!await UI.confirm({ title: 'Confirm damage assessment?', html, confirmText: 'Confirm & finalize' })) return;
      const res = Services.recordInspection(r.id, { returnDate: f.returnDate.value, items: read(), notes: f.notes.value, photos, confirmed: true });
      if (!res.ok) return UI.toast(res.error, 'error');
      m.close(); UI.toast('Inspection confirmed. Inventory updated by condition.', 'success'); done();
    };
  }

  function settleFlow(r, done) {
    const f = Finance.summary(r);
    const m = UI.modal({ title: 'Settle security deposit', body: '<div class="sum-line"><span>Deposit held</span><b>' + U.money(f.depositHeld) + '</b></div><div class="sum-line"><span>Compensation assessed</span><b>' + U.money(f.compensation) + '</b></div><div class="sum-line"><span>Compensation already paid</span><b>' + U.money(f.compPaidDirect) + '</b></div><hr>' +
      (f.compensation > 0 ? '<div class="stack-sm">' + [['deducted', 'Deduct compensation from the deposit', 'Refund ' + U.money(Math.max(0, f.depositHeld - Math.min(f.compensation, f.depositPaid))) + (f.compensation > f.depositPaid ? '; customer still owes ' + U.money(f.compensation - f.depositPaid) : '')], ['paid', 'Customer paid compensation separately', 'Refund full deposit ' + U.money(f.depositHeld)], ['waived', 'Waive compensation', 'Refund full deposit ' + U.money(f.depositHeld)]].map(([v, l, d], i) => '<label class="card card-flat row" style="padding:12px;cursor:pointer"><input type="radio" name="mode" value="' + v + '"' + (i === 0 ? ' checked' : '') + ' style="accent-color:var(--brand);width:18px;height:18px"><div><b>' + l + '</b><div class="small muted">' + d + '</div></div></label>').join('') + '</div>' : '<p>No damages — the full deposit of <b>' + U.money(f.depositHeld) + '</b> will be refunded.</p>') +
      '<p class="small muted mt-2 mb-0">A deposit refund record is created and the customer is notified. This is logged in the audit trail.</p>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Confirm settlement</button>' });
    m.el.querySelector('#ok').onclick = () => {
      const mode = (m.el.querySelector('[name=mode]:checked') || {}).value || 'settled';
      if (mode === 'deducted' && f.compensation > f.depositPaid) UI.toast('Deposit does not fully cover damages — the remaining ' + U.money(f.compensation - f.depositPaid) + ' stays due from the customer.', 'warn');
      const res = Services.settleDeposit(r.id, mode);
      if (!res.ok) return UI.toast(res.error, 'error');
      m.close(); UI.toast('Deposit settled' + (res.refund ? ' — ' + U.money(res.refund) + ' refunded.' : '.'), 'success'); done();
    };
  }

  /** Record a payment received by the shop (cash on delivery, counter, bank deposit). Verified at once with a receipt. */
  function recordCash(r, done) {
    const f = Finance.summary(r); const sug = Finance.suggestedNext(r);
    const opts = [];
    if (f.balance - f.pendingRental > 0) { opts.push([sug.type, sug.label + ' — ' + U.money(sug.amount), sug.amount]); if (sug.amount < f.balance - f.pendingRental - 0.009) opts.push([r.plan === 'full' ? 'full' : 'balance', 'Full outstanding balance — ' + U.money(f.balance - f.pendingRental), U.round2(f.balance - f.pendingRental)]); }
    if (f.depositPaid < f.depositRequired) opts.push(['deposit', 'Security deposit — ' + U.money(f.depositRequired - f.depositPaid), U.round2(f.depositRequired - f.depositPaid)]);
    if (f.compensationDue > 0) opts.push(['compensation', 'Damage compensation — ' + U.money(f.compensationDue), f.compensationDue]);
    if (!opts.length) return UI.toast('Nothing is due on this rental right now.', 'info');
    const m = UI.modal({ title: 'Record payment · ' + r.id, body: '<div class="alert alert-info mb-2">' + I('info') + '<div class="small">Use this when the customer pays your shop directly (e.g. Cash on Delivery). As ' + esc(Auth.ORG_ROLES[Auth.orgRole(Auth.session().user)]) + ' you record it as <b>verified</b> and a receipt is issued.</div></div><form id="cf" novalidate><div class="field"><label>Payment for</label><select class="input" name="kind">' + opts.map((o, i) => '<option value="' + i + '">' + esc(o[1]) + '</option>').join('') + '</select></div><div class="form-grid"><div class="field"><label>Amount (₱)</label><input class="input" type="number" step="0.01" min="1" name="amount" required></div><div class="field"><label>Method</label><select class="input" name="method"><option value="cash">Cash</option>' + (r.method === 'cod' ? '<option value="cod">Cash on Delivery</option>' : '') + '<option value="bank">Bank deposit / transfer</option></select></div><div class="field"><label>Date received</label><input class="input" type="date" name="date" value="' + U.today() + '" max="' + U.today() + '" required></div><div class="field"><label>Acknowledgment / reference no.</label><input class="input" name="reference" required placeholder="e.g. AR-0021"></div></div><div class="field"><label>Notes</label><input class="input" name="notes"></div></form>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Record & issue receipt</button>' });
    const fm = m.el.querySelector('#cf');
    const setK = () => { fm.amount.value = opts[+fm.kind.value][2]; }; fm.kind.onchange = setK; setK();
    m.el.querySelector('#ok').onclick = () => { if (!UI.validate(fm)) return; const d = UI.formData(fm); const o = opts[+d.kind]; const res = Services.recordPayment(r.id, { type: o[0], amount: +d.amount, method: d.method, reference: d.reference, date: d.date, notes: d.notes }); if (!res.ok) return UI.toast(res.error, 'error'); m.close(); UI.toast('Recorded · receipt ' + res.payment.receiptNo, 'success'); Sh().showReceipt(res.payment); done(); };
  }

  /* ================= FULFILLMENT & RETURNS ================= */
  SP.schedule = function (ctx) {
    const reqs = myReqs(ctx);
    const T = U.today();
    const cols = [['To prepare', ['accepted'], 'b-sky'], ['Preparing', ['in_progress'], 'b-purple'], ['Ready / out for delivery', ['ready_pickup', 'out_delivery'], 'b-teal'], ['With customer', ['ongoing'], 'b-pink'], ['Return pending', ['return_pending'], 'b-gold'], ['Inspection', ['inspection'], 'b-purple']];
    const events = [];
    reqs.filter(r => Finance.ACTIVE.includes(r.status)).forEach(r => { if (['accepted', 'in_progress', 'ready_pickup', 'out_delivery'].includes(r.status)) events.push({ d: r.start, kind: r.fulfillment === 'delivery' ? 'Delivery' : 'Pickup', r }); if (['accepted', 'in_progress', 'ready_pickup', 'out_delivery', 'ongoing'].includes(r.status)) events.push({ d: U.addDays(r.end, 1), kind: 'Return', r }); if (r.status === 'return_pending') events.push({ d: T, kind: 'Inspect return', r }); });
    events.sort((a, b) => a.d.localeCompare(b.d));
    ctx.el.innerHTML = '<div class="page-head"><div><h1>Fulfillment & Returns</h1><p>Move rentals through preparation, release, return and inspection.</p></div></div>' +
      '<div class="card mb-3"><div class="card-head"><h3>Rental schedule — next 14 days</h3></div>' + (events.filter(e => e.d <= U.addDays(T, 14)).length ? UI.table([{ label: 'Date', render: e => '<b>' + U.fmtDay(e.d) + '</b>' + (e.d < T ? ' <span class="badge b-red">Late</span>' : e.d === T ? ' <span class="badge b-pink">Today</span>' : '') }, { label: 'Activity', render: e => '<span class="badge ' + (e.kind === 'Return' || e.kind === 'Inspect return' ? 'b-gold' : 'b-teal') + '">' + e.kind + '</span>' }, { label: 'Request', render: e => '<a href="' + url('supplier/request.html', { id: e.r.id }) + '">' + e.r.id + '</a> · ' + esc(e.r.eventName) }, { label: 'Customer', render: e => esc(Store.user(e.r.customerId).name) }, { label: 'Items', render: e => '<span class="small">' + reqItems(e.r) + '</span>' }, { label: 'Status', render: e => UI.statusBadge(e.r.status) }], events.filter(e => e.d <= U.addDays(T, 14))) : '<p class="muted">Nothing scheduled in the next two weeks.</p>') + '</div>' +
      '<div class="grid grid-3">' + cols.map(([t, st, cls]) => { const l = reqs.filter(r => st.includes(r.status)).sort((a, b) => a.start.localeCompare(b.start)); return '<div class="card"><div class="card-head"><h3>' + t + '</h3><span class="badge ' + cls + '">' + l.length + '</span></div>' + (l.length ? l.map(r => '<a href="' + url('supplier/request.html', { id: r.id }) + '" class="card card-flat mb-1" style="display:block;padding:12px;color:inherit;text-decoration:none"><div class="row between"><b>' + r.id + '</b><span class="small muted">' + U.fmtRange(r.start, r.end) + '</span></div><div class="small">' + esc(r.eventName) + ' · ' + esc(Store.user(r.customerId).name) + '</div><div class="small muted">' + (r.fulfillment === 'delivery' ? '🚚 Delivery' : '🏬 Pickup') + ' · ' + UI.payBadge(Finance.summary(r).status) + '</div></a>').join('') : '<p class="small muted">None</p>') + '</div>'; }).join('') + '</div>';
  };

  /* ================= PRODUCTS ================= */
  SP.products = function (ctx) {
    let q = '', filter = 'all';
    ctx.el.innerHTML = '<div class="page-head"><div><h1>Products</h1><p>Your rental items. Active items appear in the marketplace, search and AI suggestions.</p></div><a class="btn btn-primary" href="' + url('supplier/product-form.html') + '">' + I('plus') + 'Add product</a></div><div class="row wrap mb-2"><input class="input input-sm" id="q" placeholder="Search products" style="width:240px" aria-label="Search"><div class="seg" id="sf"><button data-f="all" class="active">All</button><button data-f="published">Active</button><button data-f="draft">Inactive</button><button data-f="archived">Archived</button><button data-f="hidden">Hidden by admin</button></div></div><div class="card pad-0" id="lst"></div>';
    const draw = () => {
      const list = Store.where('products', p => p.supplierId === sid(ctx) && p.status !== 'deleted').filter(p => (filter === 'all' ? p.status !== 'archived' : p.status === filter) && (!q || p.name.toLowerCase().includes(q)));
      const T = U.today();
      $('#lst').innerHTML = UI.table([
        { label: 'Item', render: p => '<div class="row">' + UI.thumb(p, null, 'sm') + '<div><a class="strong" href="' + url('supplier/product-form.html', { id: p.id }) + '">' + esc(p.name) + '</a><div class="small muted">' + p.id + ' · ' + esc(Store.category(p.categoryId).name) + '</div></div></div>' },
        { label: 'Price', render: p => U.money(Pricing.basePrice(p)) + '<div class="small muted">/' + esc(p.unit) + (p.tiers.length > 1 ? ' · ' + p.tiers.length + ' tiers' : '') + (p.maxRentalDays > 0 ? ' · max ' + p.maxRentalDays + ' day' + (p.maxRentalDays > 1 ? 's' : '') + '/booking' : '') + '</div>' },
        { label: 'Stock today', render: p => { const b = Inventory.breakdown(p.id, T); return '<b>' + b.available + '</b> avail. / ' + b.total + '<div class="small muted">' + b.reserved + ' reserved · ' + (b.damaged + b.missing + b.maintenance + b.setaside) + ' unusable</div>'; } },
        { label: 'Rentals', cls: 'num', render: p => p.rentCount },
        { label: 'Status', render: p => lstBadge('product', p) + (p.status === 'archived' ? '<div class="small muted">Archived</div>' : '') + (p.status === 'hidden' && p.hiddenReason ? '<div class="small muted">' + esc(p.hiddenReason) + '</div>' : '') },
        { label: '', render: p => '<div class="btn-group"><a class="btn btn-xs" href="' + url('supplier/product-form.html', { id: p.id }) + '">' + I('edit') + 'Edit</a>' + (p.status === 'archived' ? '<button class="btn btn-xs" data-restore="' + p.id + '">Restore</button>' : p.status !== 'hidden' ? '<button class="btn btn-xs" data-toggle="' + p.id + '">' + (p.status === 'published' ? 'Deactivate' : 'Activate') + '</button><button class="btn btn-xs btn-ghost" data-archive="' + p.id + '">' + I('archive') + '</button>' : '<span class="small muted">Cannot be republished</span>') + '</div>' }
      ], list, { emptyText: 'No products here. Add your first rental item.' });
      $$('[data-toggle]').forEach(b => b.onclick = () => { const p = Store.product(b.dataset.toggle); const on = p.status !== 'published'; const r = Services.supplierSetListingActive(sid(ctx), 'product', p.id, on); if (!r.ok) return UI.toast(r.error, 'error'); UI.toast(p.name + (on ? ' is now active in the marketplace.' : ' is now inactive and hidden from customers.'), 'success'); draw(); });
      $$('[data-restore]').forEach(b => b.onclick = () => { const p = Store.product(b.dataset.restore); p.status = 'draft'; Store.save(); draw(); });
      $$('[data-archive]').forEach(b => b.onclick = async () => {
        const p = Store.product(b.dataset.archive);
        const future = Inventory.reservedDates(p.id);
        if (future.length) return UI.toast('Cannot archive — ' + p.name + ' has accepted reservations on ' + future.slice(0, 3).map(d => U.fmtDate(d)).join(', ') + (future.length > 3 ? '…' : '') + '.', 'error');
        const inPkg = Store.where('packages', k => k.active && k.items.some(it => it.productId === p.id));
        if (!await UI.confirm({ title: 'Archive ' + p.name + '?', message: 'It will be removed from the marketplace' + (inPkg.length ? ' and these packages will be deactivated: ' + inPkg.map(k => k.name).join(', ') : '') + '. Past transactions keep their history.', confirmText: 'Archive', danger: true })) return;
        p.status = 'archived'; inPkg.forEach(k => { k.active = false; }); Store.save(); Store.audit('Archived product', p.name); UI.toast('Archived.', 'success'); draw();
      });
    };
    $('#q').oninput = e => { q = e.target.value.toLowerCase(); draw(); };
    $$('#sf button').forEach(b => b.onclick = () => { filter = b.dataset.f; $$('#sf button').forEach(x => x.classList.toggle('active', x === b)); draw(); });
    draw();
  };

  SP.productForm = function (ctx) {
    const editing = ctx.params.id ? Store.product(ctx.params.id) : null;
    if (ctx.params.id && (!editing || editing.supplierId !== sid(ctx))) { ctx.el.innerHTML = UI.empty('🔒', 'Product not found', 'You can only edit your own products.'); return; }
    const p = editing ? JSON.parse(JSON.stringify(editing)) : { name: '', categoryId: '', description: '', condition: 'brand_new', value: '', unit: 'piece / day', tiers: [{ min: 1, max: null, price: 0 }], totalStock: 10, stockByLocation: {}, colors: [], themes: [], events: [], images: [], status: 'published', delivery: true, policies: '' };
    const locs = Inventory.locationsOf(sid(ctx));
    if (!editing && locs.length) p.stockByLocation = { [locs[0].id]: 10 };
    const cats = Store.where('categories', c => c.active);
    const COLORS = Object.keys(UI.COLOR_HEX), THEMES = ['Classic', 'Elegant', 'Modern', 'Minimalist', 'Pastel', 'Princess', 'Kids', 'Glam', 'Garden', 'Outdoor', 'Romantic', 'Carnival', 'Rustic', 'Fun', 'Disco'], EVENTS = Object.keys(AI.EVENTS).concat(['Community']);
    const chips = (name, list, sel) => '<div class="row wrap gap-sm">' + list.map(v => '<label class="chip ' + (sel.includes(v) ? 'active' : '') + '"><input type="checkbox" name="' + name + '" value="' + esc(v) + '" data-multi hidden' + (sel.includes(v) ? ' checked' : '') + '>' + (name === 'colors' ? UI.swatch(v) + ' ' : '') + esc(v) + '</label>').join('') + '</div>';
    const snap = editing ? Inventory.breakdown(editing.id, U.today()) : null;
    const resDates = editing ? Inventory.reservedDates(editing.id) : [];
    const maxRes = editing ? Math.max.apply(null, [0].concat(resDates.map(d => Inventory.reservedOn(editing.id, d)))) : 0;
    ctx.el.innerHTML = '<div class="crumbs"><a href="' + url('supplier/products.html') + '">Products</a> / ' + (editing ? esc(editing.name) : 'Add product') + '</div><div class="page-head"><div><h1>' + (editing ? 'Edit product' : 'Add a rental item') + '</h1>' + (editing ? '<p>' + editing.id + ' · created ' + U.fmtDate(editing.createdAt.slice(0, 10)) + '</p>' : '') + '</div>' + (editing ? '<a class="btn btn-sm" href="' + url('customer/product.html', { id: editing.id }) + '">' + I('eye') + 'View listing</a>' : '') + '</div>' +
      '<form id="pf" novalidate class="grid grid-side"><div class="stack"><div class="card"><h3>Basic information</h3><div class="field"><label>Item name</label><input class="input" name="name" required minlength="3" value="' + esc(p.name) + '" placeholder="e.g. White Monoblock Chair"></div><div class="form-grid"><div class="field"><label>Category</label><select class="input" name="categoryId" required><option value="">Select…</option>' + cats.map(c => '<option value="' + c.id + '"' + (c.id === p.categoryId ? ' selected' : '') + '>' + esc(c.name) + '</option>').join('') + '</select></div><div class="field"><label>Condition</label><select class="input" name="condition">' + Object.entries(Services.CONDITIONS).map(([k, l]) => '<option value="' + k + '"' + (k === p.condition ? ' selected' : '') + '>' + l + '</option>').join('') + '</select><div class="hint">Used for "Lost or Not Returned" compensation.</div></div><div class="field"><label>Replacement value (₱ per unit)</label><input class="input" type="number" min="1" step="0.01" name="value" required value="' + (p.value || '') + '" placeholder="e.g. 500"><div class="hint">The selling / replacement value — the basis for damage compensation (not the rental fee).</div></div></div><div class="field"><label>Description</label><textarea class="input" name="description" required minlength="15" rows="3">' + esc(p.description) + '</textarea></div>' +
      '<div class="field"><label>Product images</label><label class="upload-box" for="imgs">' + I('upload') + '<div class="small">Upload up to 4 photos (JPG/PNG). Without photos, a category illustration is shown.</div></label><input type="file" id="imgs" accept="image/*" multiple hidden><div class="thumbs" id="iv"></div></div></div>' +
      '<div class="card"><h3>Pricing</h3><div class="form-grid"><div class="field"><label>Pricing unit</label><select class="input" name="unit">' + ['piece / day', 'set / day', 'unit / day', 'pair / day', 'panel / day', 'kit / day', 'system / day'].map(u => '<option' + (u === p.unit ? ' selected' : '') + '>' + u + '</option>').join('') + '</select></div></div><div class="label mb-1">Quantity-based price tiers (per day)</div><div id="tiers"></div><button type="button" class="btn btn-sm mt-1" id="addTier">' + I('plus') + 'Add tier</button><p class="small muted mt-1 mb-0">The correct tier is applied automatically to each rental date based on the quantity that day. Changes apply to new requests only; accepted requests keep their quoted price.</p></div>' +
      '<div class="card"><h3>Tags</h3><div class="field"><label>Colors</label>' + chips('colors', COLORS, p.colors) + '</div><div class="field"><label>Themes</label>' + chips('themes', THEMES, p.themes) + '</div><div class="field"><label>Suitable events</label>' + chips('events', EVENTS, p.events) + '</div></div></div>' +
      '<aside class="stack"><div class="card"><h3>Inventory</h3>' + (locs.length ? '<div class="label mb-1">Stock per inventory location</div>' + locs.map(l => '<div class="row mb-1" style="gap:8px"><span class="grow small" style="min-width:0"><b>' + esc(l.name) + '</b><br><span class="muted">' + esc(l.address) + '</span></span><input class="input input-sm" type="number" min="0" data-loc="' + l.id + '" value="' + Inventory.stockAt(p, l.id) + '" style="width:90px" aria-label="Stock at ' + esc(l.name) + '"></div>').join('') + '<div class="sum-line strong"><span>Total inventory</span><span id="totStock">' + p.totalStock + '</span></div><div class="hint">' + (editing ? 'Highest accepted reservation at one time: <b>' + maxRes + '</b>. A location cannot go below the bookings allocated to it.' : 'Units you own at each location.') + ' <a href="' + url('supplier/locations.html') + '">Manage locations</a></div>' : '<div class="field"><label>Total stock quantity</label><input class="input" type="number" min="0" name="totalStock" required value="' + p.totalStock + '"></div>') + (snap ? '<dl class="kv small"><dt>Available today</dt><dd>' + snap.available + '</dd><dt>Reserved today</dt><dd>' + snap.reserved + '</dd><dt>Damaged</dt><dd>' + snap.damaged + '</dd><dt>Missing</dt><dd>' + snap.missing + '</dd><dt>Maintenance</dt><dd>' + snap.maintenance + '</dd><dt>Set aside</dt><dd>' + snap.setaside + '</dd></dl><a class="small strong" href="' + url('supplier/inventory.html') + '">Manage damaged / maintenance →</a>' : '') + '</div>' +
      '<div class="card"><h3>Listing</h3>' + (editing ? '<div class="field"><label>Status</label>' + (p.status === 'hidden' ? '<div>' + lstBadge('product', p) + '</div><div class="hint" style="color:var(--red)">Hidden by a PartyRent admin: ' + esc(p.hiddenReason || '') + '. You can still edit details, but you cannot republish it.</div>' : '<select class="input" name="status"><option value="published"' + (p.status === 'published' ? ' selected' : '') + '>Active (visible to customers)</option><option value="draft"' + (p.status !== 'published' ? ' selected' : '') + '>Inactive (turned off)</option></select>') + '</div>' : '<div class="alert alert-info mb-2">' + I('info') + '<div class="small">New products are <b>Active</b> and visible in the marketplace as soon as you add them.</div></div>') + '<label class="check mb-2"><input type="checkbox" name="delivery"' + (p.delivery !== false ? ' checked' : '') + '> Available for delivery</label><div class="field"><label for="maxDays">Maximum rental duration (optional)</label><label class="check mb-1"><input type="checkbox" id="noMax"' + (p.maxRentalDays > 0 ? '' : ' checked') + '> No maximum — follow normal rental rules</label><div class="row" style="gap:8px"><input class="input" type="number" min="1" max="365" step="1" id="maxDays" name="maxRentalDays" value="' + (p.maxRentalDays > 0 ? p.maxRentalDays : '') + '" placeholder="e.g. 1"' + (p.maxRentalDays > 0 ? '' : ' disabled') + ' style="max-width:110px"><span class="small muted">consecutive day(s) per booking</span></div><div class="hint">Limits how long one customer booking can keep this item (first to last day). It does not change stock or availability. Customers can still make separate bookings for other dates.</div><div class="error-text"></div></div><div class="field"><label>Rental time limits (optional)</label><div class="form-grid"><div class="field mb-0"><input class="input" type="number" min="1" max="720" name="minRentalHours" value="' + (p.minRentalHours || '') + '" placeholder="Min. hours"></div><div class="field mb-0"><input class="input" type="number" min="1" max="720" name="maxRentalHours" value="' + (p.maxRentalHours || '') + '" placeholder="Max. hours"></div></div><div class="hint">Minimum and maximum hours per booking (from start time to end time). Leave blank for no limit. Your rental hours are set in Shop Settings.</div></div><div class="field"><label>Item rental policy (optional)</label><textarea class="input" name="policies" rows="2" placeholder="e.g. Indoor use only">' + esc(p.policies || '') + '</textarea></div></div><div id="err"></div><button class="btn btn-primary btn-lg btn-block">' + (editing ? 'Save changes' : 'Add product') + '</button><a class="btn btn-ghost btn-block" href="' + url('supplier/products.html') + '">Cancel</a></aside></form>';
    const f = $('#pf');
    $$('label.chip input', f).forEach(i => i.onchange = () => i.parentElement.classList.toggle('active', i.checked));
    $$('[data-loc]', f).forEach(i => i.oninput = () => { $('#totStock').textContent = U.sum($$('[data-loc]', f), x => Math.max(0, Math.floor(+x.value || 0))); });
    $('#noMax').onchange = e => { const mx = $('#maxDays'); mx.disabled = e.target.checked; mx.required = !e.target.checked; if (e.target.checked) mx.value = ''; else { mx.value = mx.value || 1; mx.focus(); } };
    const drawImgs = () => { $('#iv').innerHTML = p.images.map((im, i) => '<div style="position:relative"><img src="' + im + '" alt=""><button type="button" class="btn btn-xs btn-danger" data-rmimg="' + i + '" style="position:absolute;top:-6px;right:-6px;padding:0 6px;min-height:22px">×</button></div>').join(''); $$('[data-rmimg]').forEach(b => b.onclick = () => { p.images.splice(+b.dataset.rmimg, 1); drawImgs(); }); };
    $('#imgs').onchange = async e => { for (const file of Array.from(e.target.files)) { if (p.images.length >= 4) break; try { p.images.push(await U.readImage(file, 700)); } catch (err) { UI.toast(err.message, 'error'); } } drawImgs(); };
    drawImgs();
    const drawTiers = () => {
      $('#tiers').innerHTML = p.tiers.map((t, i) => '<div class="row wrap mb-1" data-tier="' + i + '" style="gap:8px"><span class="small muted" style="width:46px">Tier ' + (i + 1) + '</span><input class="input input-sm" type="number" min="1" value="' + t.min + '" data-k="min" style="width:80px" aria-label="From quantity"' + (i === 0 ? ' readonly' : '') + '><span class="small">to</span>' + (i === p.tiers.length - 1 ? '<span class="small strong" style="width:80px">and up</span>' : '<input class="input input-sm" type="number" min="1" value="' + (t.max || '') + '" data-k="max" style="width:80px" aria-label="To quantity">') + '<span class="small">pcs →</span><input class="input input-sm" type="number" min="0" step="0.5" value="' + (t.price || '') + '" data-k="price" style="width:100px" placeholder="₱" aria-label="Price"><span class="small muted">/ day</span>' + (p.tiers.length > 1 ? '<button type="button" class="btn btn-xs btn-ghost" data-rmt="' + i + '">' + I('trash') + '</button>' : '') + '</div>').join('');
      $$('[data-tier] input').forEach(inp => inp.onchange = () => { const i = +inp.closest('[data-tier]').dataset.tier; p.tiers[i][inp.dataset.k] = Number(inp.value) || 0; if (inp.dataset.k === 'max' && p.tiers[i + 1]) p.tiers[i + 1].min = (Number(inp.value) || 0) + 1; drawTiers(); });
      $$('[data-rmt]').forEach(b => b.onclick = () => { p.tiers.splice(+b.dataset.rmt, 1); p.tiers[0].min = 1; for (let i = 1; i < p.tiers.length; i++) p.tiers[i].min = (p.tiers[i - 1].max || p.tiers[i - 1].min) + 1; p.tiers[p.tiers.length - 1].max = null; drawTiers(); });
    };
    $('#addTier').onclick = () => { const last = p.tiers[p.tiers.length - 1]; last.max = last.max || last.min + 9; p.tiers.push({ min: last.max + 1, max: null, price: Math.max(0, (last.price || 0) - 1) }); drawTiers(); };
    drawTiers();
    f.onsubmit = e => {
      e.preventDefault(); $('#err').innerHTML = '';
      if (!UI.validate(f)) return;
      const d = UI.formData(f);
      const sbl = {}; $$('[data-loc]', f).forEach(i => { sbl[i.dataset.loc] = Math.floor(+i.value || 0); });
      const data = { id: editing ? editing.id : undefined, name: d.name.trim(), categoryId: d.categoryId, condition: d.condition, value: +d.value, minRentalHours: d.minRentalHours, maxRentalHours: d.maxRentalHours, description: d.description.trim(), unit: d.unit, tiers: p.tiers.map(t => ({ min: +t.min, max: t.max ? +t.max : null, price: +t.price })), totalStock: locs.length ? U.sum(Object.values(sbl), Number) : Math.floor(+d.totalStock), stockByLocation: locs.length ? sbl : undefined, colors: d.colors || [], themes: d.themes || [], events: d.events || [], images: p.images, status: editing && editing.status === 'hidden' ? 'hidden' : d.status, delivery: !!d.delivery, policies: d.policies, maxRentalDays: $('#noMax').checked ? null : d.maxRentalDays };
      const res = Services.saveProduct(sid(ctx), data);
      if (!res.ok) { $('#err').innerHTML = '<div class="alert alert-danger mb-2">' + I('alert') + '<div>' + esc(res.error) + '</div></div>'; UI.toast(res.error, 'error'); return; }
      UI.toast(editing ? 'Product updated.' : 'Product added' + (data.status === 'published' ? ' and live in the marketplace.' : ' as a draft.'), 'success');
      setTimeout(() => location.href = url('supplier/products.html'), 500);
    };
  };

  /* ================= PACKAGES ================= */
  SP.packages = function (ctx) {
    const draw = () => {
      const list = Store.where('packages', k => k.supplierId === sid(ctx) && !k.deleted);
      ctx.el.innerHTML = '<div class="page-head"><div><h1>Rental Packages</h1><p>Bundles of your items at a fixed price. Reserving a package deducts each included item from inventory.</p></div><button class="btn btn-primary" id="newPk">' + I('plus') + 'Create package</button></div>' +
        (list.length ? '<div class="grid grid-2">' + list.map(k => { const v = Pricing.packageValue(k); const next30 = U.range(U.today(), U.addDays(U.today(), 29)); const minA = Math.min.apply(null, next30.map(d => Inventory.packageAvailableOn(k.id, d))); const limiting = k.items.map(it => ({ it, a: Math.floor(Inventory.availableOn(it.productId, U.today()) / it.qty) })).sort((a, b) => a.a - b.a)[0]; return '<div class="card"><div class="row top">' + UI.thumb(k, 'package') + '<div class="grow"><div class="row between"><b>' + esc(k.emoji) + ' ' + esc(k.name) + '</b>' + lstBadge('package', k) + '</div><div class="small muted">' + esc(k.description) + '</div>' + (k.hiddenByAdmin ? '<div class="small" style="color:var(--red)">Hidden by a PartyRent admin: ' + esc(k.hiddenReason || '') + '. It cannot be republished.</div>' : '') + '<div class="mt-1"><span class="price">' + U.money(k.price) + '</span> <span class="small muted">/ day · items separately ' + U.money(v.separate) + '</span></div></div></div><div class="mt-1 small">' + k.items.map(it => '<span class="tag">' + it.qty + '× ' + esc(Store.product(it.productId).name) + '</span>').join(' ') + '</div><div class="row between mt-2"><div class="small"><b>' + Inventory.packageAvailableOn(k.id, U.today()) + '</b> available today · min <b>' + minA + '</b> next 30 days' + (limiting ? '<div class="muted">Limited by ' + esc(Store.product(limiting.it.productId).name) + '</div>' : '') + '</div><div class="btn-group"><button class="btn btn-xs" data-edit="' + k.id + '">' + I('edit') + 'Edit</button>' + (k.hiddenByAdmin ? '' : '<button class="btn btn-xs" data-act="' + k.id + '">' + (k.active ? 'Deactivate' : 'Activate') + '</button>') + '</div></div></div>'; }).join('') + '</div>' : '<div class="card">' + UI.empty('📦', 'No packages yet', 'Create a bundle like "Birthday Party Package".') + '</div>');
      $('#newPk').onclick = () => form(null);
      $$('[data-edit]').forEach(b => b.onclick = () => form(Store.pkg(b.dataset.edit)));
      $$('[data-act]').forEach(b => b.onclick = () => { const k = Store.pkg(b.dataset.act); const on = !k.active; const r = Services.supplierSetListingActive(sid(ctx), 'package', k.id, on); if (!r.ok) return UI.toast(r.error, 'error'); UI.toast(k.name + (on ? ' is now active in the marketplace.' : ' is now inactive.'), 'success'); draw(); });
    };
    function form(k) {
      const items = Store.where('products', p => p.supplierId === sid(ctx) && p.status === 'published');
      const d = k ? JSON.parse(JSON.stringify(k)) : { name: '', emoji: '🎉', description: '', conditions: 'Price is per day.', events: [], price: 0, items: [], images: [], active: true };
      const m = UI.modal({ title: k ? 'Edit package' : 'Create package', size: 'lg', body: '<form id="kf" novalidate><div class="form-grid"><div class="field"><label>Package name</label><input class="input" name="name" required value="' + esc(d.name) + '"></div><div class="field"><label>Emoji / icon</label><input class="input" name="emoji" maxlength="4" value="' + esc(d.emoji) + '"></div><div class="field full"><label>Description</label><textarea class="input" name="description" required>' + esc(d.description) + '</textarea></div></div><div class="label mb-1">Included items</div><div id="ki"></div><button type="button" class="btn btn-sm" id="addKi">' + I('plus') + 'Add item</button><div class="form-grid mt-2"><div class="field"><label>Fixed package price (₱ / day)</label><input class="input" type="number" min="1" name="price" required value="' + (d.price || '') + '"><div class="hint" id="sepHint"></div></div><div class="field"><label>Events</label><input class="input" name="events" value="' + esc((d.events || []).join(', ')) + '" placeholder="Birthday, Debut"></div><div class="field full"><label>Package conditions</label><input class="input" name="conditions" value="' + esc(d.conditions) + '"></div><div class="field"><label>Minimum rental hours (optional)</label><input class="input" type="number" min="1" max="720" name="minRentalHours" value="' + (d.minRentalHours || '') + '"></div><div class="field"><label>Maximum rental hours (optional)</label><input class="input" type="number" min="1" max="720" name="maxRentalHours" value="' + (d.maxRentalHours || '') + '"></div><div class="field full"><label>Package photo</label><input type="file" id="kimg" accept="image/*" class="input"></div></div></form>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Save package</button>' });
      const drawItems = () => {
        m.el.querySelector('#ki').innerHTML = d.items.map((it, i) => '<div class="row mb-1" data-ki="' + i + '"><select class="input input-sm grow" data-k="productId">' + items.map(p => '<option value="' + p.id + '"' + (p.id === it.productId ? ' selected' : '') + '>' + esc(p.name) + ' (stock ' + p.totalStock + ')</option>').join('') + '</select><input class="input input-sm" type="number" min="1" data-k="qty" value="' + it.qty + '" style="width:90px" aria-label="Quantity"><button type="button" class="btn btn-xs btn-ghost" data-rm="' + i + '">' + I('trash') + '</button></div>').join('') || '<p class="small muted">No items yet.</p>';
        m.el.querySelectorAll('[data-ki] [data-k]').forEach(x => x.onchange = () => { const i = +x.closest('[data-ki]').dataset.ki; d.items[i][x.dataset.k] = x.dataset.k === 'qty' ? Math.max(1, +x.value || 1) : x.value; drawItems(); });
        m.el.querySelectorAll('[data-rm]').forEach(b => b.onclick = () => { d.items.splice(+b.dataset.rm, 1); drawItems(); });
        const v = Pricing.packageValue(d); m.el.querySelector('#sepHint').textContent = 'Items rented separately: ' + U.money(v.separate) + ' / day';
      };
      m.el.querySelector('#addKi').onclick = () => { if (!items.length) return UI.toast('Publish some products first.', 'warn'); d.items.push({ productId: items[0].id, qty: 1 }); drawItems(); };
      m.el.querySelector('#kimg').onchange = async e => { try { d.images = [await U.readImage(e.target.files[0], 700)]; } catch (err) { UI.toast(err.message, 'error'); } };
      drawItems();
      m.el.querySelector('#ok').onclick = () => {
        const f = m.el.querySelector('#kf'); if (!UI.validate(f)) return;
        const fd = UI.formData(f);
        const dup = new Set(); if (d.items.some(it => dup.has(it.productId) || !dup.add(it.productId))) return UI.toast('Each item can only be listed once — combine quantities instead.', 'error');
        const res = Services.savePackage(sid(ctx), Object.assign(d, { id: k ? k.id : undefined, name: fd.name.trim(), emoji: fd.emoji, description: fd.description, price: +fd.price, conditions: fd.conditions, minRentalHours: fd.minRentalHours, maxRentalHours: fd.maxRentalHours, events: fd.events.split(',').map(x => x.trim()).filter(Boolean) }));
        if (!res.ok) return UI.toast(res.error, 'error');
        m.close(); UI.toast('Package saved.', 'success'); draw();
      };
    }
    draw();
  };

  /* ================= INVENTORY ================= */
  SP.inventory = function (ctx) {
    let date = ctx.params.date || U.today();
    const draw = () => {
      const prods = myProds(ctx);
      const rows = prods.map(p => ({ p, b: Inventory.breakdown(p.id, date) }));
      const pend = myReqs(ctx).filter(r => r.status === 'pending');
      const conflicts = [];
      pend.forEach(r => Inventory.check(r.lines, { excludeRequestId: r.id }).bad.forEach(b => conflicts.push({ r, b })));
      // competing pending requests: total pending + reserved > capacity on a date
      ctx.el.innerHTML = '<div class="page-head"><div><h1>Inventory Management</h1><p>One shared calculation powers the marketplace, calendar, request review and AI.</p></div><div class="row wrap"><label class="small strong" for="dt">Check date</label><input class="input input-sm" type="date" id="dt" value="' + date + '" style="width:auto"><a class="btn btn-sm" href="' + url('supplier/calendar.html') + '">' + I('calendar') + 'Calendar</a></div></div>' +
        '<div class="alert alert-info mb-2">' + I('info') + '<div class="small"><b>Available</b> = Total − Reserved (the highest number of units booked at the same time on ' + U.fmtDate(date) + ', incl. preparation/recovery time) − Damaged − Written off − Missing − Maintenance − Set-aside. Pending requests do not consume stock. Stock per location: <a href="' + url('supplier/locations.html') + '">Inventory Locations</a>.</div></div>' +
        (conflicts.length ? '<div class="alert alert-warn mb-2">' + I('alert') + '<div><b>Potential conflicts from pending requests:</b><br>' + conflicts.map(x => '<a href="' + url('supplier/request.html', { id: x.r.id }) + '">' + x.r.id + '</a> needs ' + x.b.requested + '× ' + esc(Store.product(x.b.productId).name) + ' on ' + U.fmtDate(x.b.date) + ' — only ' + x.b.available + ' available').join('<br>') + '</div></div>' : '') +
        '<div class="stats mb-2">' + UI.stat('Total stock', U.sum(rows, x => x.b.total), '', 'layers', 'sky') + UI.stat('Reserved', U.sum(rows, x => x.b.reserved), U.fmtDate(date), 'calendar', 'pink') + UI.stat('Available', U.sum(rows, x => x.b.available), '', 'check', 'teal') + UI.stat('Damaged (to repair)', U.sum(rows, x => x.b.damaged), U.sum(rows, x => x.b.writtenOff) + ' written off', 'tool', 'red') + UI.stat('Missing', U.sum(rows, x => x.b.missing), '', 'alert', 'red') + UI.stat('Maintenance', U.sum(rows, x => x.b.maintenance), '', 'tool', 'gold') + UI.stat('Set aside', U.sum(rows, x => x.b.setaside), '', 'archive', 'purple') + UI.stat('Pending demand', U.sum(rows, x => x.b.pending), 'not reserved', 'clock', 'gold') + '</div>' +
        '<div class="card pad-0">' + UI.table([
          { label: 'Item', render: x => '<div class="row">' + UI.thumb(x.p, null, 'sm') + '<div><b>' + esc(x.p.name) + '</b><div class="small muted">' + x.p.id + '</div></div></div>' },
          { label: 'Total', cls: 'num', render: x => '<b>' + x.b.total + '</b>' }, { label: 'Reserved', cls: 'num', render: x => x.b.reserved ? '<a href="#" data-res="' + x.p.id + '">' + x.b.reserved + '</a>' : 0 },
          { label: 'Damaged', cls: 'num', render: x => x.b.damaged ? x.b.damaged + '<div class="small muted">to repair</div>' : 0 }, { label: 'Written off', cls: 'num', render: x => x.b.writtenOff }, { label: 'Missing', cls: 'num', render: x => x.b.missing }, { label: 'Maint.', cls: 'num', render: x => x.b.maintenance }, { label: 'Set aside', cls: 'num', render: x => x.b.setaside },
          { label: 'Available', cls: 'num', render: x => '<span class="avail-pill ' + (x.b.available === 0 ? 'none' : x.b.available < x.b.total * 0.2 ? 'low' : 'ok') + '">' + x.b.available + '</span>' },
          { label: 'Pending', cls: 'num', render: x => x.b.pending ? '<span style="color:' + (x.b.pending > x.b.available ? 'var(--red)' : '#B45309') + ';font-weight:700">' + x.b.pending + '</span>' : '0' },
          { label: '', render: x => '<div class="btn-group"><button class="btn btn-xs" data-stock="' + x.p.id + '">Update stock</button><button class="btn btn-xs" data-hold="' + x.p.id + '">Maintenance / set aside</button><button class="btn btn-xs btn-ghost" data-cond="' + x.p.id + '">Damaged / missing</button></div>' }
        ], rows) + '</div>' +
        '<div class="card mt-3"><h3>Maintenance & set-aside schedule</h3>' + UI.table([{ label: 'Item', render: h => esc(Store.product(h.productId).name) }, { label: 'Type', render: h => '<span class="badge ' + (h.type === 'setaside' ? 'b-purple' : 'b-gold') + '">' + (h.type === 'setaside' ? 'Set aside' : 'Maintenance') + '</span>' }, { label: 'Qty', cls: 'num', key: 'qty' }, { label: 'From', render: h => U.fmtDate(h.start) }, { label: 'Until', render: h => h.end ? U.fmtDate(h.end) : 'Until released' }, { label: 'Note', render: h => esc(h.note) }, { label: '', render: h => '<button class="btn btn-xs" data-release="' + h.id + '">Release</button>' }], Store.where('holds', h => { const p = Store.product(h.productId); return p && p.supplierId === sid(ctx) && (!h.end || h.end >= U.today()); }), { emptyText: 'No active holds.' }) + '</div>';
      $('#dt').onchange = e => { date = e.target.value || U.today(); draw(); };
      $$('[data-stock]').forEach(b => b.onclick = () => stockModal(Store.product(b.dataset.stock)));
      $$('[data-hold]').forEach(b => b.onclick = () => holdModal(Store.product(b.dataset.hold)));
      $$('[data-cond]').forEach(b => b.onclick = () => condModal(Store.product(b.dataset.cond)));
      $$('[data-repair]').forEach(b => b.onclick = async () => { const p = Store.product(b.dataset.repair); const v = await UI.prompt({ title: 'Mark repaired · ' + p.name, message: p.damaged + ' unit(s) are waiting for repair. Repaired units become available again.', label: 'Units repaired', value: String(p.damaged), required: true, confirmText: 'Mark repaired' }); if (v == null) return; const res = Services.markRepaired(p.id, +v); if (!res.ok) return UI.toast(res.error, 'error'); UI.toast('Units returned to available stock.', 'success'); draw(); });
      $$('[data-release]').forEach(b => b.onclick = async () => { if (!await UI.confirm({ title: 'Release hold?', message: 'These units return to available stock.', confirmText: 'Release' })) return; const h = Store.get('holds', b.dataset.release); h.end = U.addDays(U.today(), -1); Store.save(); Store.audit('Released inventory hold', Store.product(h.productId).name + ' · ' + h.qty); UI.toast('Units returned to available stock.', 'success'); draw(); });
      $$('[data-res]').forEach(a => a.onclick = e => { e.preventDefault(); const refs = Inventory.demandOn(a.dataset.res, date, Inventory.RESERVING).refs; UI.modal({ title: 'Reserved on ' + U.fmtDate(date), body: refs.map(x => '<div class="sum-line"><a href="' + url('supplier/request.html', { id: x.requestId }) + '">' + x.requestId + '</a><b>' + x.qty + ' units</b></div>').join('') }); });
    };
    function stockModal(p) {
      const locs = Inventory.locationsOf(p.supplierId);
      const m = UI.modal({ title: 'Update stock · ' + p.name, body: '<p class="small muted">Each inventory location keeps its own dedicated quantity. The total is always the sum of all locations. To move units between locations use <a href="' + url('supplier/locations.html', { product: p.id }) + '">Transfer stock</a>.</p>' + locs.map(l => { const peak = Math.max.apply(null, [0].concat(Inventory.reservedDates(p.id, l.id).map(d => Inventory.demandOn(p.id, d, Inventory.RESERVING, null, null, l.id).total))); return '<div class="field"><label>' + esc(l.name) + '</label><input class="input" type="number" min="0" data-loc="' + l.id + '" value="' + Inventory.stockAt(p, l.id) + '"><div class="hint">Peak booking allocated here: <b>' + peak + '</b></div></div>'; }).join('') + '<div class="sum-line strong"><span>Total inventory</span><span id="tot">' + p.totalStock + '</span></div><div id="se"></div>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Save</button>' });
      const sum = () => { m.el.querySelector('#tot').textContent = U.sum($$('[data-loc]', m.el), i => Math.max(0, Math.floor(+i.value || 0))); };
      $$('[data-loc]', m.el).forEach(i => i.oninput = sum);
      m.el.querySelector('#ok').onclick = () => {
        const sbl = {}; $$('[data-loc]', m.el).forEach(i => { sbl[i.dataset.loc] = Math.floor(+i.value || 0); });
        const res = Services.saveProduct(sid(ctx), Object.assign(JSON.parse(JSON.stringify(Store.product(p.id))), { stockByLocation: sbl }));
        if (res.busy) return UI.toast(res.error, 'warn');
        if (!res.ok) { m.el.querySelector('#se').innerHTML = '<div class="alert alert-danger">' + I('alert') + '<div><b>Update blocked.</b> ' + esc(res.error) + '</div></div>'; return; }
        Store.audit('Updated stock per location', p.name + ': ' + locs.map(l => l.name + ' ' + (sbl[l.id] || 0)).join(', '));
        m.close(); UI.toast('Stock updated (total ' + Store.product(p.id).totalStock + ').', 'success'); draw();
      };
    }
    function holdModal(p) {
      const m = UI.modal({ title: 'Maintenance / set aside · ' + p.name, size: 'sm', body: '<form id="hf" novalidate><div class="field"><label>Type</label><select class="input" name="type"><option value="maintenance">Maintenance / repair</option><option value="setaside">Set aside (display, personal use)</option></select></div><div class="field"><label>Quantity</label><input class="input" type="number" min="1" name="qty" required value="1"></div><div class="form-grid"><div class="field"><label>From</label><input class="input" type="date" name="start" required value="' + U.today() + '"></div><div class="field"><label>Until (optional)</label><input class="input" type="date" name="end"></div></div><div class="field"><label>Note</label><input class="input" name="note" required placeholder="e.g. Repainting"></div></form><div id="he"></div>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Set aside units</button>' });
      m.el.querySelector('#ok').onclick = () => { const f = m.el.querySelector('#hf'); if (!UI.validate(f)) return; const d = UI.formData(f); const res = Services.addHold(p.id, { type: d.type, qty: Math.floor(+d.qty), start: d.start, end: d.end || null, note: d.note }); if (!res.ok) { m.el.querySelector('#he').innerHTML = '<div class="alert alert-danger">' + I('alert') + '<div>' + esc(res.error) + '</div></div>'; return; } Store.audit('Added inventory hold', p.name + ' · ' + d.qty + ' ' + d.type); m.close(); UI.toast('Units moved to ' + (d.type === 'setaside' ? 'set-aside' : 'maintenance') + '.', 'success'); draw(); };
    }
    function condModal(p) {
      const m = UI.modal({ title: 'Damaged & missing units · ' + p.name, size: 'sm', body: '<p class="small muted">Lower these numbers when units are repaired or found — they return to available stock. Raise them to report new losses.</p><div class="form-grid"><div class="field"><label>Damaged units</label><input class="input" type="number" min="0" id="dm" value="' + (p.damaged || 0) + '"></div><div class="field"><label>Missing units</label><input class="input" type="number" min="0" id="ms" value="' + (p.missing || 0) + '"></div></div><div id="ce"></div>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Save</button>' });
      m.el.querySelector('#ok').onclick = () => {
        const dm = Math.floor(+m.el.querySelector('#dm').value), ms = Math.floor(+m.el.querySelector('#ms').value);
        const c = Inventory.stockChangeConflicts(p.id, p.totalStock, dm, ms);
        if (c.length) { m.el.querySelector('#ce').innerHTML = '<div class="alert alert-danger">' + I('alert') + '<div>This would leave too few units for accepted reservations on ' + c.map(x => U.fmtDate(x.date)).join(', ') + '.</div></div>'; return; }
        let r = Services.adjustCondition(p.id, 'damaged', dm); if (r.ok) r = Services.adjustCondition(p.id, 'missing', ms);
        if (!r.ok) return UI.toast(r.error, 'error'); m.close(); UI.toast('Inventory condition updated.', 'success'); draw();
      };
    }
    draw();
  };

  /* ================= INVENTORY CALENDAR ================= */
  SP.calendar = function (ctx) {
    const prods = myProds(ctx);
    if (!prods.length) { ctx.el.innerHTML = UI.empty('📅', 'No items yet', 'Add a product to see its calendar.'); return; }
    let pid = ctx.params.item || prods[0].id, view = 'month', cursor = U.today(), sel = U.today();
    function cell(d, inMonth) {
      const b = Inventory.breakdown(pid, d);
      const ret = myReqs(ctx).filter(r => Finance.ACTIVE.includes(r.status) && U.addDays(r.end, 1) === d && Object.values(r.lines).some(l => Inventory.unitsForLine(l, r.end)[pid])).length;
      const cls = b.available === 0 ? 'none' : b.available < b.total * 0.25 ? 'low' : 'ok';
      return '<div class="c ' + (inMonth ? '' : 'out') + (d === sel ? ' sel' : '') + '" data-d="' + d + '"><div class="dn"><span>' + U.parse(d).getDate() + '<span class="wk"> ' + (view !== 'month' ? U.DOW[U.parse(d).getDay()] : '') + '</span></span>' + (d === U.today() ? '<span class="badge b-purple plain" style="padding:0 6px">Today</span>' : '') + '</div><div class="avail-pill ' + cls + '">' + b.available + ' free</div>' + (b.reserved ? '<div class="bar res">' + b.reserved + ' reserved</div>' : '') + (b.pending ? '<div class="bar pen">' + b.pending + ' pending</div>' : '') + (b.maintenance + b.setaside ? '<div class="bar mnt">' + (b.maintenance + b.setaside) + ' maint./aside</div>' : '') + (ret ? '<div class="bar ret">' + ret + ' return' + (ret > 1 ? 's' : '') + '</div>' : '') + '</div>';
    }
    function draw() {
      const p = Store.product(pid);
      let grid = '';
      if (view === 'month') {
        const first = U.parse(cursor.slice(0, 7) + '-01'); const start = U.addDays(U.iso(first), -first.getDay());
        const m = first.getMonth();
        grid = '<div class="icals">' + U.DOW.map(x => '<div class="h">' + x + '</div>').join('') + U.range(start, U.addDays(start, 41)).map(d => cell(d, U.parse(d).getMonth() === m)).join('') + '</div>';
      } else if (view === 'week') {
        const c = U.parse(cursor); const start = U.addDays(cursor, -c.getDay());
        grid = '<div class="icals">' + U.DOW.map(x => '<div class="h">' + x + '</div>').join('') + U.range(start, U.addDays(start, 6)).map(d => cell(d, true)).join('') + '</div>';
      }
      const title = view === 'month' ? U.MONTHS[U.parse(cursor).getMonth()] + ' ' + U.parse(cursor).getFullYear() : view === 'week' ? 'Week of ' + U.fmtDate(U.addDays(cursor, -U.parse(cursor).getDay())) : U.fmtDay(cursor);
      ctx.el.innerHTML = '<div class="page-head"><div><h1>Inventory Calendar</h1><p>Select an item to see its rental schedule.</p></div><div class="row wrap"><select class="input input-sm" id="it" style="width:auto;max-width:260px" aria-label="Item">' + prods.map(x => '<option value="' + x.id + '"' + (x.id === pid ? ' selected' : '') + '>' + esc(x.name) + '</option>').join('') + '</select><div class="seg" id="vw"><button data-v="day">Day</button><button data-v="week">Week</button><button data-v="month">Month</button></div></div></div>' +
        '<div class="grid" style="grid-template-columns:minmax(0,1fr) 320px;align-items:start" id="calGrid"><div class="card"><div class="row between mb-2"><button class="btn btn-sm btn-icon" id="prev" aria-label="Previous">' + I('left') + '</button><div class="strong">' + title + ' · ' + esc(p.name) + ' (' + p.totalStock + ' total)</div><button class="btn btn-sm btn-icon" id="next" aria-label="Next">' + I('right') + '</button></div>' + (view === 'day' ? '<div id="dayView"></div>' : grid) +
        '<div class="legend mt-2"><span><i style="background:var(--green-50)"></i>Plenty free</span><span><i style="background:var(--gold-50)"></i>Low (&lt;25%)</span><span><i style="background:var(--red-50)"></i>Fully booked</span><span><i style="background:var(--purple-50)"></i>Accepted reservations</span><span><i style="background:var(--gold-50);border:1px dashed #B45309"></i>Pending requests</span><span><i style="background:#F1EEF4"></i>Maintenance</span><span><i style="background:var(--teal-50)"></i>Returns</span></div></div><aside class="card" id="detail"></aside></div>';
      if (window.matchMedia('(max-width:1024px)').matches) $('#calGrid').style.gridTemplateColumns = '1fr';
      $$('#vw button').forEach(b => { b.classList.toggle('active', b.dataset.v === view); b.onclick = () => { view = b.dataset.v; if (view === 'day') cursor = sel; draw(); }; });
      $('#it').onchange = e => { pid = e.target.value; draw(); };
      const step = view === 'month' ? 0 : view === 'week' ? 7 : 1;
      $('#prev').onclick = () => { if (view === 'month') { const d = U.parse(cursor); cursor = U.iso(new Date(d.getFullYear(), d.getMonth() - 1, 1)); } else cursor = U.addDays(cursor, -step); if (view === 'day') sel = cursor; draw(); };
      $('#next').onclick = () => { if (view === 'month') { const d = U.parse(cursor); cursor = U.iso(new Date(d.getFullYear(), d.getMonth() + 1, 1)); } else cursor = U.addDays(cursor, step); if (view === 'day') sel = cursor; draw(); };
      $$('.icals .c').forEach(c => c.onclick = () => { sel = c.dataset.d; $$('.icals .c').forEach(x => x.classList.toggle('sel', x === c)); detail(); });
      if (view === 'day') { sel = cursor; $('#dayView').innerHTML = dayDetail(sel, true); }
      detail();
    }
    function dayDetail(d, big) {
      const b = Inventory.breakdown(pid, d);
      const rows = b.reservedRefs.map(x => ({ x, kind: 'Accepted' })).concat(b.pendingRefs.map(x => ({ x, kind: 'Pending' })));
      return '<h3>' + U.fmtDay(d) + '</h3><dl class="kv"><dt>Total stock</dt><dd>' + b.total + '</dd><dt>Reserved</dt><dd>' + b.reserved + '</dd><dt>Damaged / missing</dt><dd>' + b.damaged + ' / ' + b.missing + '</dd><dt>Maintenance</dt><dd>' + b.maintenance + '</dd><dt>Set aside</dt><dd>' + b.setaside + '</dd><dt>Available</dt><dd><span class="avail-pill ' + (b.available ? 'ok' : 'none') + '">' + b.available + '</span></dd><dt>Pending demand</dt><dd>' + b.pending + (b.pending > b.available ? ' <span class="badge b-red">exceeds available</span>' : '') + '</dd></dl><div class="label mt-2 mb-1">Bookings this day</div>' + (rows.length ? rows.map(({ x, kind }) => { const r = Store.request(x.requestId); return '<a class="row between" href="' + url('supplier/request.html', { id: r.id }) + '" style="padding:8px 0;border-bottom:1px solid var(--line);color:inherit;text-decoration:none"><div><b>' + r.id + '</b> · ' + x.qty + ' units<div class="small muted">' + esc(Store.user(r.customerId).name) + ' · ' + esc(r.eventName) + '</div></div><span class="badge ' + (kind === 'Pending' ? 'b-gold' : 'b-purple') + '">' + kind + '</span></a>'; }).join('') : '<p class="small muted">No bookings.</p>') + (b.holds.length ? '<div class="label mt-2 mb-1">Holds</div>' + b.holds.map(h => '<div class="small">• ' + h.qty + ' ' + (h.type === 'setaside' ? 'set aside' : 'in maintenance') + ' — ' + esc(h.note) + '</div>').join('') : '');
    }
    function detail() { $('#detail').innerHTML = dayDetail(sel); }
    draw();
  };

  /* ================= PAYMENTS ================= */
  SP.payments = function (ctx) {
    const reqs = myReqs(ctx).filter(r => Finance.ACTIVE.includes(r.status) || r.status === 'completed' || r.status === 'cancelled');
    const ids = new Set(reqs.map(r => r.id));
    const canVerify = Auth.canFinance(sid(ctx), 'payments.verify');
    let tab = ctx.params.tab || (canVerify ? 'verify' : 'balances');
    const draw = () => {
      const fins = reqs.map(r => ({ r, f: Finance.summary(r) }));
      const pays = Store.where('payments', p => ids.has(p.requestId)).sort((a, b) => (b.submittedAt || '').localeCompare(a.submittedAt || ''));
      const pend = pays.filter(p => p.status === 'pending');
      const collected = U.sum(pays.filter(p => p.status === 'verified' && Finance.RENTAL_TYPES.includes(p.type)), p => p.amount);
      const cashiers = Store.where('users', u => u.supplierId === sid(ctx) && u.orgRole === 'cashier' && u.status === 'active');
      ctx.el.innerHTML = '<div class="page-head"><div><h1>Payment Monitoring</h1><p>Your shop verifies its own payments' + (cashiers.length ? ' (Cashier: ' + cashiers.map(u => esc(u.name)).join(', ') + ')' : ' — as an individual supplier you can verify and record them yourself, or add a Cashier under Team & Roles') + '. Only verified payments count toward balances.</p></div></div><div class="stats mb-3">' + UI.stat('Collected (verified)', U.moneyShort(collected), 'rental payments', 'check', 'teal') + UI.stat('Awaiting verification', U.moneyShort(U.sum(pend, p => p.amount)), pend.length + ' submissions', 'clock', 'gold') + UI.stat('Outstanding balances', U.moneyShort(U.sum(fins.filter(x => Finance.ACTIVE.includes(x.r.status)), x => x.f.balance)), '', 'cash', 'pink') + UI.stat('Overdue', U.moneyShort(U.sum(fins.filter(x => x.f.isOverdue), x => x.f.overdueAmount)), fins.filter(x => x.f.isOverdue).length + ' rentals', 'alert', 'red') + UI.stat('Deposits held', U.moneyShort(U.sum(fins, x => x.f.depositHeld)), 'refundable — not income', 'shield', 'purple') + '</div>' +
        UI.tabs([{ key: 'verify', label: 'Verification queue', count: pend.length }, { key: 'balances', label: 'Balances by order' }, { key: 'overdue', label: 'Overdue', count: fins.filter(x => x.f.isOverdue).length }, { key: 'history', label: 'Payment records', count: pays.length }], tab) + '<div class="card pad-0" id="pc"></div>';
      $$('[data-tab]').forEach(t => t.onclick = () => { tab = t.dataset.tab; draw(); });
      const payCols = [{ label: 'Transaction', render: p => '<b>' + p.id + '</b><div class="small muted">' + U.fmtDate(p.date) + '</div>' }, { label: 'Request', render: p => '<a href="' + url('supplier/request.html', { id: p.requestId }) + '">' + p.requestId + '</a>' }, { label: 'Customer', render: p => esc(Store.user(Store.request(p.requestId).customerId).name) }, { label: 'Type', render: p => Finance.TYPE_LABEL[p.type] }, { label: 'Method', render: p => (Finance.METHOD_LABEL[p.method] || p.method) + '<div class="small muted">' + esc(p.reference) + '</div>' }, { label: 'Amount', cls: 'num', render: p => '<b>' + U.money(p.amount) + '</b>' }, { label: 'Status', render: p => UI.verBadge(p.status) }];
      if (tab === 'verify') $('#pc').innerHTML = UI.table(payCols.concat([{ label: '', render: p => '<button class="btn btn-xs ' + (canVerify ? 'btn-primary' : '') + '" data-review="' + p.id + '">' + (canVerify ? 'Review' : 'View') + '</button>' }]), pend, { emptyText: 'No payments waiting for verification 🎉' });
      else if (tab === 'history') $('#pc').innerHTML = UI.table(payCols.concat([{ label: '', render: p => '<button class="btn btn-xs" data-pay="' + p.id + '">View</button>' }]), pays);
      else $('#pc').innerHTML = UI.table([{ label: 'Request', render: x => '<a class="strong" href="' + url('supplier/request.html', { id: x.r.id }) + '">' + x.r.id + '</a><div class="small muted">' + esc(x.r.eventName) + '</div>' }, { label: 'Customer', render: x => esc(Store.user(x.r.customerId).name) }, { label: 'Payment plan', render: x => '<span class="small">' + Finance.PLAN_LABEL[x.r.plan] + '</span>' }, { label: 'Total', cls: 'num', render: x => U.money(x.f.payable) }, { label: 'Paid', cls: 'num', render: x => U.money(x.f.paidRental) }, { label: 'Outstanding', cls: 'num', render: x => '<b>' + U.money(x.f.balance) + '</b>' }, { label: 'Next deadline', render: x => x.f.next ? '<span class="small">' + esc(x.f.next.label) + '<br>' + U.fmtDate(x.f.next.due) + '</span>' : '—' }, { label: 'Deposit', render: x => '<span class="small">' + esc(x.f.depositStatus) + '</span>' }, { label: 'Status', render: x => UI.payBadge(x.f.status) }], fins.filter(x => tab === 'overdue' ? x.f.isOverdue : true).sort((a, b) => b.f.balance - a.f.balance));
      $$('[data-review]').forEach(b => b.onclick = () => Sh().reviewPayment(Store.get('payments', b.dataset.review), draw));
    };
    draw();
  };

  /* ================= DAMAGE & COMPENSATION ================= */
  SP.damages = function (ctx) {
    const list = myReqs(ctx).filter(r => r.inspection).sort((a, b) => b.inspection.at.localeCompare(a.inspection.at));
    const n = (r, k) => U.sum(r.inspection.items || [], i => i[k] || 0);
    const withDmg = list.filter(r => r.inspection.compensation > 0 || n(r, 'repairable') + n(r, 'nonRepairable') + n(r, 'lost') > 0);
    const sup = Store.supplier(sid(ctx)); const pol = Services.damagePolicy(sup);
    ctx.el.innerHTML = '<div class="page-head"><div><h1>Damage & Compensation</h1><p>Confirmed return inspections, evidence and settlement status. Compensation is recorded separately from rental income.</p></div>' + (Auth.orgCan('shop.manage', ctx.session.user) ? '<a class="btn btn-sm" href="' + url('supplier/shop.html', { tab: 'damage' }) + '">' + I('settings') + 'Damage policy</a>' : '') + '</div>' +
      '<div class="card mb-2"><b>Your current policy</b><div class="row wrap gap-sm mt-1"><span class="badge b-gray">Repairable: ' + (pol.repairable.enabled ? pol.repairable.pct + '%' : 'off') + '</span><span class="badge b-gray">Non-repairable: ' + (pol.nonRepairable.enabled ? pol.nonRepairable.pct + '%' : 'off') + '</span><span class="badge b-gray">Lost — Brand New ' + pol.lost.brand_new + '% · Good as New ' + pol.lost.good_as_new + '% · Used ' + pol.lost.used + '%' + (pol.lost.enabled ? '' : ' (off)') + '</span>' + Object.keys(pol.categories).map(c => '<span class="badge b-purple plain">' + esc((Store.category(c) || {}).name || c) + ' rule</span>').join('') + '</div><p class="small muted mb-0 mt-1">Compensation = product value × compensation % × affected quantity.</p></div>' +
      '<div class="stats mb-3">' + UI.stat('Inspections', list.length, '', 'check', 'teal') + UI.stat('With damage / loss', withDmg.length, '', 'tool', 'red') + UI.stat('Compensation assessed', U.moneyShort(U.sum(list, r => r.inspection.compensation)), '', 'cash', 'purple') + UI.stat('Pending settlement', list.filter(r => r.inspection.settlement === 'pending').length, U.moneyShort(U.sum(list, r => Finance.summary(r).compensationDue)) + ' due', 'clock', 'gold') + '</div>' +
      '<div class="card pad-0">' + UI.table([{ label: 'Request', render: r => '<a class="strong" href="' + url('supplier/request.html', { id: r.id }) + '">' + r.id + '</a><div class="small muted">' + esc(Store.user(r.customerId).name) + '</div>' }, { label: 'Confirmed', render: r => U.fmtDate((r.inspection.confirmedAt || r.inspection.at).slice(0, 10)) }, { label: 'Repairable', cls: 'num', render: r => n(r, 'repairable') }, { label: 'Non-repairable', cls: 'num', render: r => n(r, 'nonRepairable') }, { label: 'Lost', cls: 'num', render: r => n(r, 'lost') }, { label: 'Compensation', cls: 'num', render: r => U.money(r.inspection.compensation) }, { label: 'Settlement', render: r => '<span class="badge ' + (r.inspection.settlement === 'pending' ? 'b-red' : 'b-green') + '">' + U.cap(r.inspection.settlement) + '</span>' }, { label: 'Evidence', render: r => (r.inspection.photos || []).length ? r.inspection.photos.length + ' photo(s)' : '—' }, { label: '', render: r => '<a class="btn btn-xs" href="' + url('supplier/request.html', { id: r.id }) + '">Open</a>' }], list, { emptyText: 'No inspections recorded yet.' }) + '</div>';
  };

  /* ================= REPORTS ================= */
  SP.reports = function (ctx) {
    let range = 'month', from, to;
    const setRange = () => { const T = U.today(); if (range === 'month') { from = T.slice(0, 7) + '-01'; to = T; } else if (range === '3m') { const d = U.parse(T); from = U.iso(new Date(d.getFullYear(), d.getMonth() - 2, 1)); to = T; } else if (range === 'year') { from = T.slice(0, 4) + '-01-01'; to = T; } };
    setRange();
    const draw = () => {
      const reqs = myReqs(ctx); const ids = new Set(reqs.map(r => r.id));
      const pays = Store.where('payments', p => ids.has(p.requestId) && p.status === 'verified' && p.date >= from && p.date <= to);
      const income = U.sum(pays.filter(p => Finance.RENTAL_TYPES.includes(p.type)), p => p.amount) - U.sum(pays.filter(p => p.type === 'refund'), p => p.amount);
      const inRange = reqs.filter(r => r.createdAt.slice(0, 10) >= from && r.createdAt.slice(0, 10) <= to);
      const days = U.range(U.diffDays(from, to) > 45 ? U.addDays(to, -29) : from, to);
      const prods = myProds(ctx);
      const next30 = U.range(U.today(), U.addDays(U.today(), 29));
      const util = prods.map(p => { const cap = U.sum(next30, d => Math.max(0, p.totalStock - (p.damaged || 0) - (p.missing || 0))); const used = U.sum(next30, d => Inventory.reservedOn(p.id, d)); return { p, pct: cap ? used / cap * 100 : 0, used }; }).sort((a, b) => b.pct - a.pct);
      const units = {}; reqs.filter(r => !['declined', 'cancelled', 'pending'].includes(r.status)).forEach(r => Object.values(Inventory.demandMap(r.lines)).forEach(m => Object.entries(m).forEach(([pid, q]) => { units[pid] = (units[pid] || 0) + q; })));
      const outstanding = reqs.filter(r => Finance.ACTIVE.includes(r.status)).map(r => ({ r, f: Finance.summary(r) })).filter(x => x.f.balance > 0);
      const dmg = reqs.filter(r => r.inspection && r.inspection.compensation > 0);
      const upcoming = reqs.filter(r => ['accepted', 'in_progress', 'ready_pickup', 'out_delivery'].includes(r.status)).sort((a, b) => a.start.localeCompare(b.start));
      ctx.el.innerHTML = '<div class="page-head"><div><h1>Business Reports</h1><p>' + U.fmtRange(from, to) + '</p></div><div class="row wrap"><div class="seg" id="rg"><button data-r="month">This month</button><button data-r="3m">Last 3 months</button><button data-r="year">This year</button><button data-r="custom">Custom</button></div><span class="range-inline"><input type="date" class="input input-sm" id="rf" value="' + from + '" aria-label="From"><input type="date" class="input input-sm" id="rt" value="' + to + '" aria-label="To"></span><button class="btn btn-sm" id="csv">' + I('copy') + 'Copy CSV</button></div></div>' +
        '<div class="stats mb-3">' + UI.stat('Rental income', U.moneyShort(income), 'verified, net of refunds', 'chart', 'teal') + UI.stat('Requests received', inRange.length, inRange.filter(r => r.status === 'declined').length + ' declined', 'list', 'purple') + UI.stat('Outstanding balances', U.moneyShort(U.sum(outstanding, x => x.f.balance)), outstanding.length + ' rentals', 'cash', 'pink') + UI.stat('Damage & loss', U.moneyShort(U.sum(dmg, r => r.inspection.compensation)), dmg.length + ' incidents', 'tool', 'red') + '</div>' +
        '<div class="grid grid-2"><div class="card"><h3>Daily rental transactions</h3><div id="d1"></div></div><div class="card"><h3>Monthly rental transactions</h3><div id="d2"></div></div><div class="card"><h3>Rental income by month</h3><div id="d3"></div></div><div class="card"><h3>Most rented products</h3><div id="d4"></div></div>' +
        '<div class="card"><h3>Inventory utilization · next 30 days</h3><p class="small muted">Reserved unit-days ÷ usable unit-days</p><div id="d5"></div></div><div class="card"><h3>Outstanding balances</h3>' + UI.table([{ label: 'Request', render: x => '<a href="' + url('supplier/request.html', { id: x.r.id }) + '">' + x.r.id + '</a>' }, { label: 'Customer', render: x => esc(Store.user(x.r.customerId).name) }, { label: 'Balance', cls: 'num', render: x => U.money(x.f.balance) }, { label: 'Status', render: x => UI.payBadge(x.f.status) }], outstanding, { emptyText: 'No outstanding balances.' }) + '</div>' +
        '<div class="card"><h3>Damage & loss report</h3>' + UI.table([{ label: 'Request', render: r => r.id }, { label: 'Items', render: r => r.inspection.items.filter(i => i.major || i.total || i.missing || i.minor).map(i => esc(Store.product(i.productId).name) + ': ' + ((i.minor || 0) + (i.major || 0) + (i.total || 0)) + ' dmg, ' + (i.missing || 0) + ' missing').join('<br>') || '—' }, { label: 'Charged', cls: 'num', render: r => U.money(r.inspection.compensation) }], dmg, { emptyText: 'No damage recorded.' }) + '</div><div class="card"><h3>Upcoming reservations</h3>' + UI.table([{ label: 'Dates', render: r => U.fmtRange(r.start, r.end) }, { label: 'Request', render: r => '<a href="' + url('supplier/request.html', { id: r.id }) + '">' + r.id + '</a>' }, { label: 'Units', cls: 'num', render: r => reqQty(r) }, { label: 'Amount', cls: 'num', render: r => U.money(r.pricing.payable) }], upcoming, { emptyText: 'None.' }) + '</div></div>';
      $$('#rg button').forEach(b => { b.classList.toggle('active', b.dataset.r === range); b.onclick = () => { range = b.dataset.r; if (range !== 'custom') setRange(); draw(); }; });
      $('#rf').onchange = $('#rt').onchange = () => { range = 'custom'; from = $('#rf').value; to = $('#rt').value; if (to < from) to = from; draw(); };
      Charts.bars($('#d1'), days.map(d => ({ label: String(U.parse(d).getDate()), value: reqs.filter(r => r.createdAt.slice(0, 10) === d).length })), { color: '#7C3AED' });
      const months = Charts.months(6);
      Charts.bars($('#d2'), months.map(m => ({ label: m.label, value: reqs.filter(r => r.createdAt.slice(0, 7) === m.key).length })), { color: '#E11D74' });
      const allVer = Store.where('payments', p => ids.has(p.requestId) && p.status === 'verified');
      Charts.line($('#d3'), months.map(m => ({ label: m.label, value: U.sum(allVer.filter(p => p.date.slice(0, 7) === m.key && Finance.RENTAL_TYPES.includes(p.type)), p => p.amount) - U.sum(allVer.filter(p => p.date.slice(0, 7) === m.key && p.type === 'refund'), p => p.amount) })), { money: true, color: '#0D9488' });
      Charts.hbars($('#d4'), Object.entries(units).map(([pid, v]) => ({ label: Store.product(pid).name, value: v })).sort((a, b) => b.value - a.value).slice(0, 8));
      $('#d5').innerHTML = util.map(x => '<div class="hbar"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(x.p.name) + '</span><div class="tr"><span style="width:' + Math.min(100, x.pct) + '%;background:#7C3AED"></span></div><b class="right">' + x.pct.toFixed(1) + '%</b></div>').join('');
      $('#csv').onclick = async () => { const rows = [['Request', 'Customer', 'Event', 'Start', 'End', 'Status', 'Total', 'Paid', 'Balance', 'Payment status']].concat(inRange.map(r => { const f = Finance.summary(r); return [r.id, Store.user(r.customerId).name, r.eventName, r.start, r.end, Services.statusLabel(r.status), f.payable, f.paidRental, f.balance, f.status]; })); const csv = rows.map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(',')).join('\n'); try { await navigator.clipboard.writeText(csv); UI.toast('CSV copied — paste into Excel or Google Sheets.', 'success'); } catch (e) { UI.modal({ title: 'CSV export', body: '<textarea class="input" rows="12" readonly>' + esc(csv) + '</textarea>' }); } };
    };
    draw();
  };

  /* ================= SHOP PROFILE & SETTINGS ================= */
  SP.shop = function (ctx) {
    const s = Store.supplier(sid(ctx));
    let tab = ctx.params.tab || 'profile';
    const allTimes = Array.from({ length: 49 }, (_, i) => Slots.fromMin(i * 30));
    const tsel = (name, v) => '<select class="input" name="' + name + '">' + allTimes.map(t => '<option value="' + t + '"' + (t === v ? ' selected' : '') + '>' + Slots.fmt12(t) + '</option>').join('') + '</select>';
    // working copies for the editable lists
    let zones = JSON.parse(JSON.stringify(s.deliveryZones || []));
    let services = JSON.parse(JSON.stringify(s.services || []));
    let dmg = JSON.parse(JSON.stringify(Services.damagePolicy(s)));
    const pctIn = (name, v, extra) => '<div class="row" style="gap:6px"><input class="input" type="number" min="0" max="100" step="0.5" name="' + name + '" value="' + v + '" ' + (extra || '') + '><span class="small muted">%</span></div>';
    const dmgBlock = (pre, o) => '<div class="grid grid-3"><div class="card card-flat" style="padding:12px"><label class="check"><input type="checkbox" name="' + pre + 'rep_on"' + (o.repairable.enabled ? ' checked' : '') + '> <b>Repairable Damage</b></label><div class="small muted mb-1">Can be repaired and reused</div>' + pctIn(pre + 'rep_pct', o.repairable.pct) + '</div><div class="card card-flat" style="padding:12px"><label class="check"><input type="checkbox" name="' + pre + 'non_on"' + (o.nonRepairable.enabled ? ' checked' : '') + '> <b>Non-Repairable Damage</b></label><div class="small muted mb-1">Cannot be repaired or safely used</div>' + pctIn(pre + 'non_pct', o.nonRepairable.pct) + '</div><div class="card card-flat" style="padding:12px"><label class="check"><input type="checkbox" name="' + pre + 'lost_on"' + (o.lost.enabled ? ' checked' : '') + '> <b>Lost or Not Returned</b></label><div class="small muted mb-1">By condition before rental</div>' + [['brand_new', 'Brand New'], ['good_as_new', 'Good as New'], ['used', 'Used']].map(([k, l]) => '<label class="small">' + l + '</label>' + pctIn(pre + 'lost_' + k, o.lost[k])).join('') + '</div></div>';
    const readDmg = (f, pre) => ({ repairable: { enabled: f[pre + 'rep_on'].checked, pct: +f[pre + 'rep_pct'].value }, nonRepairable: { enabled: f[pre + 'non_on'].checked, pct: +f[pre + 'non_pct'].value }, lost: { enabled: f[pre + 'lost_on'].checked, brand_new: +f[pre + 'lost_brand_new'].value, good_as_new: +f[pre + 'lost_good_as_new'].value, used: +f[pre + 'lost_used'].value } });
    const draw = () => {
      const p = s.policy; const cfg = Finance.planConfig(s); const ts = Slots.settings(s.id);
      const ex = (k) => { const c = cfg[k]; if (k === 'full') return 'On ₱10,000: one payment of ₱10,000.00.'; const res = 10000 * c.resPct / 100, dn = 10000 * c.downPct / 100; return 'On ₱10,000: reservation fee ' + U.money(res) + ' + down payment ' + U.money(dn) + ' + ' + (k === 'installment' ? 'installments' : 'final balance') + ' ' + U.money(10000 - res - dn) + ' = ₱10,000.00 (never added on top).'; };
      const planCard = (k, inner) => '<div class="card card-flat mb-2" style="padding:14px"><label class="check"><input type="checkbox" name="' + k + '_on"' + (cfg[k].enabled ? ' checked' : '') + '> <b>' + Finance.PLAN_LABEL[k] + '</b></label><div class="form-grid mt-1">' + inner + '</div><div class="small muted">' + ex(k) + '</div></div>';
      const pf = (k, n, label, v, attrs) => '<div class="field"><label>' + label + '</label><input class="input" type="number" name="' + k + '_' + n + '" value="' + v + '" ' + (attrs || 'min="0"') + '></div>';
      const forms = {
        profile: '<div class="form-grid"><div class="field"><label>Business name</label><input class="input" name="name" required value="' + esc(s.name) + '"></div><div class="field"><label>Logo (emoji)</label><div class="row"><input class="input" name="logo" maxlength="4" value="' + esc(s.logo) + '" style="width:90px"><label class="btn btn-sm" for="lg">' + I('upload') + 'Upload image</label><input type="file" id="lg" accept="image/*" hidden>' + (s.logoImg ? '<img src="' + s.logoImg + '" style="width:40px;height:40px;border-radius:10px;object-fit:cover" alt="">' : '') + '</div></div><div class="field full"><label>Business description</label><textarea class="input" name="description" required>' + esc(s.description) + '</textarea></div><div class="field"><label>Contact number</label><input class="input" name="phone" data-phone required value="' + esc(s.phone) + '"></div><div class="field"><label>Email address</label><input class="input" type="email" name="email" required value="' + esc(s.email) + '"></div><div class="field full"><label>Business address</label><input class="input" name="address" required value="' + esc(s.address) + '"></div><div class="field"><label>Business location (city)</label><input class="input" name="city" required value="' + esc(s.city) + '"></div><div class="field"><label>Operating hours</label><input class="input" name="hours" required value="' + esc(s.hours) + '"></div><div class="field"><label>Brand color</label><input class="input" type="color" name="color" value="' + s.color + '" style="height:44px;padding:4px"></div><div class="field"><label>Supplier type</label><div><span class="badge b-purple">' + esc(Services.SUPPLIER_TYPES[s.type] || 'Individual Supplier') + '</span></div></div></div>',
        delivery: '<div class="stack-sm">' + [['delivery', 'Delivery only'], ['pickup', 'Pickup only'], ['both', 'Both delivery and pickup']].map(([v, l]) => '<label class="check"><input type="radio" name="fulfillment" value="' + v + '"' + (s.fulfillment === v ? ' checked' : '') + '> ' + l + '</label>').join('') + '</div><div class="label mt-2 mb-1">Delivery zones & rates</div><p class="small muted">Delivery fees are charged <b>per delivery location</b>. A customer delivering to a church and a reception pays the fee for each.</p><div id="zones">' + zones.map((z, i) => '<div class="row mb-1" style="gap:8px" data-z="' + i + '"><input class="input input-sm grow" data-zk="name" value="' + esc(z.name) + '" placeholder="Zone name, e.g. Quezon City" aria-label="Zone name"><input class="input input-sm" type="number" min="0" data-zk="fee" value="' + z.fee + '" style="width:110px" aria-label="Fee"><button type="button" class="btn btn-xs btn-ghost" data-rmz="' + i + '">' + I('trash') + '</button></div>').join('') + '</div><button type="button" class="btn btn-sm" id="addZ">' + I('plus') + 'Add zone</button><div class="field mt-2"><label>Standard rate for other areas (₱ per location)</label><input class="input" type="number" min="0" name="deliveryFee" value="' + (s.deliveryFee || 0) + '" style="max-width:200px"></div>',
        hours: '<p class="small muted">Customers pick their rental start and end time within these hours (12-hour format). Preparation (delivery & setup) and recovery (dismantling & pickup) time is <b>added around every booking</b> when checking stock, so the same units can be rented again later the same day only when the times don\'t overlap.</p><div class="form-grid"><div class="field"><label>Rental hours start</label>' + tsel('open', ts.open) + '</div><div class="field"><label>Rental hours end</label>' + tsel('close', ts.close) + '</div><div class="field"><label>Preparation time before each booking (hours)</label><input class="input" type="number" min="0" max="24" step="0.5" name="prepHours" value="' + ts.prepHours + '"></div><div class="field"><label>Recovery time after each booking (hours)</label><input class="input" type="number" min="0" max="24" step="0.5" name="recoveryHours" value="' + ts.recoveryHours + '"></div></div><div class="alert alert-info">' + I('info') + '<div class="small">Example with your settings: a 6:00 AM – 11:00 AM booking blocks the units from ' + Slots.fmt12(Math.max(0, 360 - ts.prepHours * 60)) + ' to ' + Slots.fmt12(660 + ts.recoveryHours * 60) + '. Minimum / maximum hours per booking are set on each product or package.</div></div>',
        plans: '<div class="field"><label>Accepted payment methods</label>' + [['cod', 'Cash on Delivery'], ['bank', 'Online Bank Transfer'], ['debit', 'Debit']].map(([v, l]) => '<label class="check"><input type="checkbox" name="methods" data-multi value="' + v + '"' + (s.methods.includes(v) ? ' checked' : '') + '> ' + l + '</label>').join(' ') + '</div>' +
          '<p class="small muted">Payment deadlines count from the day you accept a request and never go past the event date. Reservation fees are non-refundable and, like down payments, always credited to the order total.</p>' +
          planCard('standard', pf('standard', 'resPct', 'Reservation fee (%)', cfg.standard.resPct, 'min="0" max="100" step="0.5"') + pf('standard', 'resDays', 'Reservation fee due within (days)', cfg.standard.resDays) + pf('standard', 'downPct', 'Down payment (%)', cfg.standard.downPct, 'min="0" max="100" step="0.5"') + pf('standard', 'downDays', 'Down payment due within (days)', cfg.standard.downDays)) +
          planCard('full', pf('full', 'days', 'Full payment due within (days)', cfg.full.days)) +
          planCard('installment', pf('installment', 'resPct', 'Reservation fee (%)', cfg.installment.resPct, 'min="0" max="100" step="0.5"') + pf('installment', 'resDays', 'Reservation fee due within (days)', cfg.installment.resDays) + pf('installment', 'downPct', 'Down payment (%)', cfg.installment.downPct, 'min="0" max="100" step="0.5"') + pf('installment', 'downDays', 'Down payment due within (days)', cfg.installment.downDays) + pf('installment', 'minMonths', 'Minimum months before the event', cfg.installment.minMonths, 'min="1" max="24"') + pf('installment', 'maxInstallments', 'Maximum number of installments', cfg.installment.maxInstallments, 'min="1" max="24"')) +
          '<div class="field"><label>Security deposit (separate, refundable)</label><div class="row" style="gap:6px"><select class="input" name="depositType" style="width:130px"><option value="fixed"' + (p.depositType === 'fixed' ? ' selected' : '') + '>₱ fixed</option><option value="percent"' + (p.depositType === 'percent' ? ' selected' : '') + '>% of rental fee</option></select><input class="input" type="number" min="0" name="depositValue" value="' + p.depositValue + '"></div></div><p class="small muted mb-0">Changes apply to new requests; accepted orders keep the terms they were quoted.</p>',
        services: '<p class="small muted">Services appear as separate Service Fee lines in the customer\'s Rental Charges. <b>Included</b> services are always added; optional ones are chosen by the customer at checkout. "Per location" multiplies the fee by the number of delivery locations.</p><div id="svcs">' + services.map((x, i) => '<div class="card card-flat mb-1" style="padding:12px" data-sv="' + i + '"><div class="form-grid"><div class="field"><label class="small">Service</label><input class="input input-sm" data-sk="name" value="' + esc(x.name) + '" placeholder="e.g. Setup and installation"></div><div class="field"><label class="small">Amount (₱)</label><input class="input input-sm" type="number" min="0" data-sk="amount" value="' + x.amount + '"></div><div class="field full"><label class="small">What is included</label><input class="input input-sm" data-sk="description" value="' + esc(x.description) + '"></div><div class="field"><label class="small">Charged</label><select class="input input-sm" data-sk="per"><option value="order"' + (x.per !== 'location' ? ' selected' : '') + '>Once per order</option><option value="location"' + (x.per === 'location' ? ' selected' : '') + '>Per delivery location</option></select></div><div class="field"><label class="check mt-2"><input type="checkbox" data-sk="required"' + (x.required ? ' checked' : '') + '> Always included</label></div></div><button type="button" class="btn btn-xs btn-ghost" data-rmsv="' + i + '">' + I('trash') + 'Remove</button></div>').join('') + '</div><button type="button" class="btn btn-sm" id="addSv">' + I('plus') + 'Add service</button>',
        damage: '<p class="small muted">Compensation = product replacement value × compensation % × affected quantity. Customers are only charged after you review and confirm an inspection.</p><div class="label mb-1">Shop default</div>' + dmgBlock('d_', dmg) +
          '<div class="label mt-3 mb-1">Rules for specific product categories (optional)</div>' + Object.keys(dmg.categories).map(cid => '<div class="card card-flat mb-2" style="padding:12px" data-cat="' + cid + '"><div class="row between mb-1"><b>' + esc((Store.category(cid) || {}).name || cid) + '</b><button type="button" class="btn btn-xs btn-ghost" data-rmcat="' + cid + '">' + I('trash') + 'Remove rule</button></div>' + dmgBlock('c_' + cid + '_', Object.assign({}, dmg, dmg.categories[cid], { repairable: Object.assign({}, dmg.repairable, (dmg.categories[cid] || {}).repairable), nonRepairable: Object.assign({}, dmg.nonRepairable, (dmg.categories[cid] || {}).nonRepairable), lost: Object.assign({}, dmg.lost, (dmg.categories[cid] || {}).lost) })) + '</div>').join('') +
          '<div class="row" style="gap:8px"><select class="input input-sm" id="newCat" style="width:auto"><option value="">Add a rule for category…</option>' + Store.where('categories', c => c.active && !dmg.categories[c.id]).map(c => '<option value="' + c.id + '">' + esc(c.name) + '</option>').join('') + '</select><button type="button" class="btn btn-sm" id="addCat">' + I('plus') + 'Add rule</button></div>',
        policies: '<div class="field"><label>Free cancellation window (days before rental)</label><input class="input" type="number" min="0" name="cancelDays" value="' + p.cancelDays + '" style="max-width:200px"></div><div class="field"><label>Cancellation policy</label><textarea class="input" name="cancellation" required>' + esc(p.cancellation) + '</textarea></div><div class="field"><label>Return policy</label><textarea class="input" name="returns" required>' + esc(p.returns) + '</textarea></div><div class="field"><label>Rental conditions / business policies</label><textarea class="input" name="conditions" required>' + esc(p.conditions) + '</textarea></div>'
      };
      ctx.el.innerHTML = '<div class="page-head"><div><h1>Shop Profile & Settings</h1><p>' + esc(s.name) + ' · <a href="' + url('customer/supplier.html', { id: s.id }) + '">View public shop</a></p></div></div>' + UI.tabs([{ key: 'profile', label: 'Shop profile' }, { key: 'delivery', label: 'Delivery & pickup' }, { key: 'hours', label: 'Rental hours' }, { key: 'plans', label: 'Payment plans' }, { key: 'services', label: 'Services & fees' }, { key: 'damage', label: 'Damage policy' }, { key: 'policies', label: 'Business policies' }], tab) + '<form class="card" id="sf" novalidate style="max-width:900px">' + forms[tab] + '<div class="row end mt-2"><button class="btn btn-primary">Save changes</button></div></form>';
      $$('[data-tab]').forEach(t => t.onclick = () => { tab = t.dataset.tab; zones = JSON.parse(JSON.stringify(s.deliveryZones || [])); services = JSON.parse(JSON.stringify(s.services || [])); dmg = JSON.parse(JSON.stringify(Services.damagePolicy(s))); draw(); });
      const f = $('#sf');
      const lg = $('#lg'); if (lg) lg.onchange = async e => { try { s.logoImg = await U.readImage(e.target.files[0], 240); Store.save(); draw(); } catch (err) { UI.toast(err.message, 'error'); } };
      // editable lists keep their typed values when rows are added or removed
      const syncZones = () => $$('[data-z]', f).forEach(row => { const z = zones[+row.dataset.z]; row.querySelectorAll('[data-zk]').forEach(i => { z[i.dataset.zk] = i.dataset.zk === 'fee' ? +i.value : i.value; }); });
      const syncSvc = () => $$('[data-sv]', f).forEach(row => { const x = services[+row.dataset.sv]; row.querySelectorAll('[data-sk]').forEach(i => { x[i.dataset.sk] = i.type === 'checkbox' ? i.checked : i.dataset.sk === 'amount' ? +i.value : i.value; }); });
      const syncDmg = () => { if (!f.d_rep_on) return; Object.assign(dmg, readDmg(f, 'd_')); Object.keys(dmg.categories).forEach(c => { if (f['c_' + c + '_rep_on']) dmg.categories[c] = readDmg(f, 'c_' + c + '_'); }); };
      const az = $('#addZ'); if (az) az.onclick = () => { syncZones(); zones.push({ id: '', name: '', fee: 0 }); draw(); };
      $$('[data-rmz]').forEach(b => b.onclick = () => { syncZones(); zones.splice(+b.dataset.rmz, 1); draw(); });
      const as = $('#addSv'); if (as) as.onclick = () => { syncSvc(); services.push({ id: '', name: '', description: '', amount: 0, per: 'order', required: false }); draw(); };
      $$('[data-rmsv]').forEach(b => b.onclick = () => { syncSvc(); services.splice(+b.dataset.rmsv, 1); draw(); });
      const ac = $('#addCat'); if (ac) ac.onclick = () => { const c = $('#newCat').value; if (!c) return UI.toast('Choose a category.', 'warn'); syncDmg(); dmg.categories[c] = { repairable: Object.assign({}, dmg.repairable), nonRepairable: Object.assign({}, dmg.nonRepairable), lost: Object.assign({}, dmg.lost) }; draw(); };
      $$('[data-rmcat]').forEach(b => b.onclick = () => { syncDmg(); delete dmg.categories[b.dataset.rmcat]; draw(); });
      f.onsubmit = e => {
        e.preventDefault(); if (!UI.validate(f)) return; const d = UI.formData(f);
        let res = { ok: true };
        if (tab === 'profile') { Object.assign(s, { name: d.name.trim(), logo: d.logo || s.logo, description: d.description, phone: d.phone, email: d.email, address: d.address, city: d.city, hours: d.hours, color: d.color }); Store.save(); }
        if (tab === 'delivery') {
          syncZones();
          const clash = myReqs(ctx).filter(r => Finance.ACTIVE.includes(r.status) && ((d.fulfillment === 'pickup' && r.fulfillment === 'delivery') || (d.fulfillment === 'delivery' && r.fulfillment === 'pickup')));
          if (clash.length) UI.toast('Note: ' + clash.length + ' accepted rental(s) still use the previous fulfillment option and will be honored.', 'warn');
          res = Services.saveShopSettings(s.id, 'delivery', { fulfillment: d.fulfillment, deliveryFee: d.deliveryFee, deliveryZones: zones });
        }
        if (tab === 'hours') res = Services.saveShopSettings(s.id, 'hours', { timeSettings: { open: d.open, close: d.close, prepHours: d.prepHours, recoveryHours: d.recoveryHours } });
        if (tab === 'plans') {
          const num = k => +f[k].value;
          const pp = { standard: { enabled: f.standard_on.checked, resPct: num('standard_resPct'), resDays: num('standard_resDays'), downPct: num('standard_downPct'), downDays: num('standard_downDays') }, full: { enabled: f.full_on.checked, days: num('full_days') }, installment: { enabled: f.installment_on.checked, resPct: num('installment_resPct'), resDays: num('installment_resDays'), downPct: num('installment_downPct'), downDays: num('installment_downDays'), minMonths: num('installment_minMonths'), maxInstallments: num('installment_maxInstallments') } };
          res = Services.saveShopSettings(s.id, 'plans', { paymentPlans: pp, methods: d.methods || [], depositType: d.depositType, depositValue: d.depositValue });
        }
        if (tab === 'services') { syncSvc(); res = Services.saveShopSettings(s.id, 'services', { services }); }
        if (tab === 'damage') { syncDmg(); res = Services.saveShopSettings(s.id, 'damage', { damagePolicy: dmg }); }
        if (tab === 'policies') { Object.assign(s.policy, { cancelDays: +d.cancelDays || 0, cancellation: d.cancellation, returns: d.returns, conditions: d.conditions }); Store.save(); }
        if (!res.ok) return UI.toast(res.error, 'error');
        UI.toast('Shop settings saved.', 'success'); draw();
      };
    };
    draw();
  };

  /* ================= INVENTORY LOCATIONS ================= */
  SP.locations = function (ctx) {
    const s = Store.supplier(sid(ctx));
    let pf = ctx.params.product || '';
    const draw = () => {
      const locs = s.locations || [];
      const prods = myProds(ctx).filter(p => p.status !== 'archived');
      const moves = (Store.load().movements || []).filter(m => m.supplierId === s.id).slice().reverse().slice(0, 40);
      ctx.el.innerHTML = '<div class="page-head"><div><h1>Inventory Locations</h1><p>Warehouses, branches and storage facilities. Each location keeps its own dedicated stock; the total inventory is the sum of all locations and stock is never duplicated.</p></div><button class="btn btn-primary" id="addLoc">' + I('plus') + 'Add location</button></div>' +
        '<div class="grid grid-3 mb-3">' + locs.map(l => { const units = U.sum(prods, p => Inventory.stockAt(p, l.id)); return '<div class="card"><div class="row between"><b>' + I('map').replace('<svg', '<svg style="width:16px;vertical-align:-3px"') + ' ' + esc(l.name) + '</b><span class="badge b-purple">' + units + ' units</span></div><div class="small muted mt-1">' + esc(l.address) + '</div><div class="small mt-1">' + esc(l.contact || '—') + (l.phone ? ' · ' + esc(l.phone) : '') + '</div><div class="btn-group mt-2"><button class="btn btn-xs" data-edit="' + l.id + '">' + I('edit') + 'Edit</button><button class="btn btn-xs btn-ghost" data-del="' + l.id + '">' + I('trash') + 'Remove</button></div></div>'; }).join('') + '</div>' +
        '<div class="card pad-0 mb-3"><div class="card-head" style="padding:16px 18px 0"><h3>Stock by location</h3><span class="small muted">Available today per location (after bookings allocated there)</span></div>' + UI.table([{ label: 'Product', render: p => '<b>' + esc(p.name) + '</b><div class="small muted">' + p.id + '</div>' }].concat(locs.map(l => ({ label: l.name, cls: 'num', render: p => { const st = Inventory.stockAt(p, l.id); return st ? '<b>' + st + '</b><div class="small muted">' + Inventory.availableAt(p.id, l.id, U.today()) + ' free today</div>' : '<span class="muted">0</span>'; } }))).concat([{ label: 'Total', cls: 'num', render: p => '<b>' + p.totalStock + '</b>' }, { label: '', render: p => locs.length > 1 ? '<button class="btn btn-xs" data-move="' + p.id + '">Transfer</button>' : '' }]), prods) + '</div>' +
        '<div class="card"><div class="card-head"><h3>Inventory movement records</h3><span class="small muted">Latest 40</span></div>' + UI.table([{ label: 'When', render: m => '<span class="small">' + U.fmtDateTime(m.at) + '</span>' }, { label: 'Product', render: m => esc((Store.product(m.productId) || {}).name || m.productId) }, { label: 'Movement', render: m => '<span class="badge b-gray plain">' + esc(Services.MOVE_LABEL[m.type] || m.type) + '</span>' }, { label: 'Qty', cls: 'num', render: m => (m.qty > 0 && m.type === 'adjust' ? '+' : '') + m.qty }, { label: 'From → To', render: m => (m.from ? esc(Services.locName(s.id, m.from)) : '') + (m.to ? ' → ' + esc(Services.locName(s.id, m.to)) : '') || '—' }, { label: 'By', render: m => esc((Store.user(m.by) || { name: 'System' }).name) }, { label: 'Note', render: m => '<span class="small">' + esc(m.note) + '</span>' }], moves, { emptyText: 'No movements recorded yet. Transfers, stock counts, write-offs and losses appear here.' }) + '</div>';
      $('#addLoc').onclick = () => locForm(null);
      $$('[data-edit]').forEach(b => b.onclick = () => locForm(locs.find(l => l.id === b.dataset.edit)));
      $$('[data-del]').forEach(b => b.onclick = async () => { const l = locs.find(x => x.id === b.dataset.del); if (!await UI.confirm({ title: 'Remove ' + l.name + '?', message: 'Only empty locations without allocated bookings can be removed.', confirmText: 'Remove', danger: true })) return; const r = Services.deleteLocation(s.id, l.id); if (!r.ok) return UI.toast(r.error, 'error'); UI.toast('Location removed.', 'success'); draw(); });
      $$('[data-move]').forEach(b => b.onclick = () => transfer(Store.product(b.dataset.move)));
      if (pf) { const p = Store.product(pf); pf = ''; if (p && p.supplierId === s.id && locs.length > 1) transfer(p); }
    };
    function locForm(l) {
      const m = UI.modal({ title: l ? 'Edit location' : 'Add inventory location', body: '<form id="lf" novalidate><div class="field"><label>Location name</label><input class="input" name="name" required value="' + esc(l ? l.name : '') + '" placeholder="e.g. Main Warehouse, Branch A"></div><div class="field"><label>Complete address</label><input class="input" name="address" required minlength="8" value="' + esc(l ? l.address : '') + '"></div><div class="form-grid"><div class="field"><label>Contact person / representative</label><input class="input" name="contact" value="' + esc(l ? l.contact : '') + '"></div><div class="field"><label>Contact number</label><input class="input" name="phone" value="' + esc(l ? l.phone : '') + '"></div></div></form>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Save</button>' });
      m.el.querySelector('#ok').onclick = () => { const f = m.el.querySelector('#lf'); if (!UI.validate(f)) return; const r = Services.saveLocation(s.id, Object.assign(UI.formData(f), { id: l ? l.id : undefined })); if (!r.ok) return UI.toast(r.error, 'error'); m.close(); UI.toast('Location saved.', 'success'); draw(); };
    }
    function transfer(p) {
      const locs = s.locations;
      const m = UI.modal({ title: 'Transfer stock · ' + p.name, body: '<p class="small muted">Moves units from one location to another and records the movement. Units already allocated to bookings at the source location cannot be moved.</p><form id="tf" novalidate><div class="form-grid"><div class="field"><label>From</label><select class="input" name="from">' + locs.map(l => '<option value="' + l.id + '">' + esc(l.name) + ' (' + Inventory.stockAt(p, l.id) + ')</option>').join('') + '</select></div><div class="field"><label>To</label><select class="input" name="to">' + locs.map((l, i) => '<option value="' + l.id + '"' + (i === 1 ? ' selected' : '') + '>' + esc(l.name) + ' (' + Inventory.stockAt(p, l.id) + ')</option>').join('') + '</select></div><div class="field"><label>Quantity</label><input class="input" type="number" min="1" name="qty" required value="1"></div><div class="field"><label>Note (optional)</label><input class="input" name="note" placeholder="e.g. For the Pasig wedding"></div></div></form>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Transfer</button>' });
      m.el.querySelector('#ok').onclick = () => { const f = m.el.querySelector('#tf'); if (!UI.validate(f)) return; const d = UI.formData(f); const r = Services.transferStock(p.id, d.from, d.to, +d.qty, d.note); if (!r.ok) return UI.toast(r.error, 'error'); m.close(); UI.toast('Transferred ' + d.qty + ' unit(s).', 'success'); draw(); };
    }
    draw();
  };

  /* ================= TEAM & ROLES (Organization Admin) ================= */
  SP.team = function (ctx) {
    const s = Store.supplier(sid(ctx));
    const draw = () => {
      const members = Services.orgMembers(s.id);
      const R = Auth.ORG_ROLES;
      ctx.el.innerHTML = '<div class="page-head"><div><h1>Team & Roles</h1><p>' + (s.type === 'organization' ? 'Your organization\'s employee accounts. Everyone works under <b>' + esc(s.name) + '</b> and only sees this shop\'s data.' : 'Employee accounts are <b>optional</b> for individual suppliers — you can handle payments and inventory yourself. Add a cashier or inventory staff when your business grows.') + '</p></div><button class="btn btn-primary" id="add">' + I('plus') + 'Add employee</button></div>' +
        '<div class="card pad-0 mb-3">' + UI.table([{ label: 'Member', render: x => '<div class="row"><span class="avatar">' + U.initials(x.user.name) + '</span><div><b>' + esc(x.user.name) + '</b><div class="small muted">' + esc(x.user.email) + '</div></div></div>' }, { label: 'Role', render: x => '<span class="badge ' + ({ org_admin: 'b-purple', cashier: 'b-teal', inventory: 'b-sky', staff: 'b-gray' }[x.orgRoleKey]) + '">' + esc(R[x.orgRoleKey]) + '</span>' }, { label: 'Status', render: x => '<span class="badge ' + (x.user.status === 'active' ? 'b-green' : 'b-gray') + '">' + U.cap(x.user.status) + '</span>' }, { label: 'Added', render: x => '<span class="small">' + U.fmtDate(x.user.createdAt.slice(0, 10)) + '</span>' }, { label: '', render: x => x.orgRoleKey === 'org_admin' ? '<span class="small muted">Account owner</span>' : '<div class="btn-group"><button class="btn btn-xs" data-role="' + x.user.id + '">Change role</button><button class="btn btn-xs" data-pw="' + x.user.id + '">Reset password</button><button class="btn btn-xs ' + (x.user.status === 'active' ? 'btn-ghost' : 'btn-success') + '" data-st="' + x.user.id + '">' + (x.user.status === 'active' ? 'Deactivate' : 'Reactivate') + '</button></div>' }], members) + '</div>' +
        '<div class="card"><h3>What each role can do</h3><div class="table-wrap"><table class="table"><thead><tr><th>Permission</th>' + Object.values(R).map(l => '<th class="center">' + esc(l) + '</th>').join('') + '</tr></thead><tbody>' + Auth.ORG_PERM_LIST.map(([k, l]) => '<tr><td>' + esc(l) + '</td>' + Object.keys(R).map(r => '<td class="center">' + (Auth.ORG_PERMS[r].includes(k) ? '<span class="perm-yes">✓</span>' : '<span class="perm-no">—</span>') + '</td>').join('') + '</tr>').join('') + '</tbody></table></div><p class="small muted mb-0 mt-1">Cashiers handle this shop\'s payments, receipts and financial reports only — they cannot manage other suppliers, platform settings, customer accounts or organization administrators. Platform administration stays with PartyRent.</p></div>';
      $('#add').onclick = add;
      $$('[data-role]').forEach(b => b.onclick = async () => { const u = Store.user(b.dataset.role); const m = UI.modal({ title: 'Change role · ' + u.name, size: 'sm', body: '<div class="field"><label>Role</label><select class="input" id="nr">' + Services.EMPLOYEE_ROLES.map(r => '<option value="' + r + '"' + (r === u.orgRole ? ' selected' : '') + '>' + R[r] + '</option>').join('') + '</select></div>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Save</button>' }); m.el.querySelector('#ok').onclick = () => { const r = Services.updateEmployee(s.id, u.id, { role: m.el.querySelector('#nr').value }); if (!r.ok) return UI.toast(r.error, 'error'); m.close(); UI.toast('Role updated.', 'success'); draw(); }; });
      $$('[data-pw]').forEach(b => b.onclick = async () => { const u = Store.user(b.dataset.pw); const v = await UI.prompt({ title: 'Reset password · ' + u.name, label: 'New temporary password (8+ characters)', value: Math.random().toString(36).slice(2, 10) + 'A1', required: true, confirmText: 'Reset' }); if (v == null) return; const r = Services.updateEmployee(s.id, u.id, { password: v }); if (!r.ok) return UI.toast(r.error, 'error'); UI.toast('Password reset. Share it securely.', 'success'); });
      $$('[data-st]').forEach(b => b.onclick = async () => { const u = Store.user(b.dataset.st); const on = u.status !== 'active'; if (!await UI.confirm({ title: (on ? 'Reactivate ' : 'Deactivate ') + u.name + '?', message: on ? 'They can sign in again.' : 'They will no longer be able to sign in. Their past actions stay in the records.', confirmText: on ? 'Reactivate' : 'Deactivate', danger: !on })) return; const r = Services.updateEmployee(s.id, u.id, { status: on ? 'active' : 'deactivated' }); if (!r.ok) return UI.toast(r.error, 'error'); draw(); });
    };
    function add() {
      const m = UI.modal({ title: 'Add employee', body: '<form id="ef" novalidate><div class="field"><label>Full name</label><input class="input" name="name" required minlength="3"></div><div class="form-grid"><div class="field"><label>Email (their login)</label><input class="input" type="email" name="email" required></div><div class="field"><label>Contact number</label><input class="input" name="phone" data-phone></div></div><div class="field"><label>Role</label><select class="input" name="role">' + Services.EMPLOYEE_ROLES.map(r => '<option value="' + r + '">' + Auth.ORG_ROLES[r] + '</option>').join('') + '</select><div class="hint">Cashier: payments & receipts · Inventory Staff: products, stock & locations · Staff: assigned operations (deliveries, returns).</div></div><div class="field"><label>Temporary password</label><input class="input" name="password" required minlength="8" value="' + Math.random().toString(36).slice(2, 10) + 'A1"></div></form>', foot: '<button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="ok">Create account</button>' });
      m.el.querySelector('#ok').onclick = () => { const f = m.el.querySelector('#ef'); if (!UI.validate(f)) return; const r = Services.addEmployee(s.id, UI.formData(f)); if (!r.ok) return UI.toast(r.error, 'error'); m.close(); UI.toast(r.user.name + ' added as ' + Auth.ORG_ROLES[r.user.orgRole] + '. Share the temporary password securely.', 'success'); draw(); };
    }
    draw();
  };
})();
